window.SOCIAL_DATA=window.SOCIAL_DATA||[];window.SOCIAL_DATA.push({"id": "civ-3", "subject": "公民", "chapter": "第三章", "title": "法治與權力分立", "total": 275, "levels": {"必考": 28, "常考": 14}, "mapname": {"c3-map-powers": "三權分立與五權分立示意圖", "c4-map-budget": "中央政府預算、決算流程簡圖"}, "concepts": [{"id": "c1", "name": "人治與法治", "n": 70, "level": "必考", "card": {"說明": "人治是指統治者憑藉個人好惡與意志來治理國家，統治者的意志即為法律，統治者本身不受法律約束。相對地，法治是指人民與政府都必須受到法律的約束，法律是全民共同遵守的最高規範。民主國家採行法治，主要目的在於保障人民的基本權利，並以法律嚴格規範與限制政府權力，確保政府在執法時具備明確依據，使人民能預期法律的法律效果。", "關鍵名詞": "• <b>人治</b>：指統治者依據個人好惡統治人民，統治者不受法律約束且可任意變更法律的治理方式。<br>• <b>法治</b>：指政府與人民皆須遵守法律規範，政府公權力行使必須嚴格受法律限制與約束的制度。<br>• <b>依法行政</b>：指行政機關行使公權力時必須依循法律規定，不得任意侵犯人民權利。", "因果／影響": "在人治社會中，法律淪為鞏固統治者權力與限制人民的工具，朝令夕改導致人民權利無法獲得保障；而在法治社會中，政府依法行政且受法律監督，能有效防止政府權力濫用，人民的基本生活與自由權利獲得切實保障。", "出處": "自修第 261～264 頁／講義第 29～30 頁（試題寶典評量第 21 頁、速讀秘笈第 3 頁）。", "標示": "講義標為「<b>重點分析</b>」，評量單與速讀秘笈列為「<b>必考重點／易錯題型</b>」。"}, "imgs": [], "clusters": [{"t": "人治：統治者的意思就是法律", "n": 54, "ids": ["c3-1", "c3-2", "c3-3", "c3-10", "c3-13", "c3-15", "c3-25", "c3-29", "c3-39", "c3-40", "c3-43", "c3-44", "c3-54", "c3-55", "c3-58", "c3-69", "c3-71", "c3-72", "c3-73", "c3-75", "c3-76", "c3-78", "c3-79", "c3-80", "c3-81", "c3-83", "c3-85", "c3-87", "c3-95", "c3-96", "c3-98", "c3-102", "c3-105", "c3-108", "c3-115", "c3-125", "c3-149", "c3-154", "c3-155", "c3-175", "c3-177", "c3-181", "c3-183", "c3-186", "c3-195", "c3-200", "c3-204", "c3-219", "c3-221", "c3-240", "c3-308", "c3-311", "c3-312", "c3-329"]}, {"t": "法治：政府依法行政、受法律約束", "n": 9, "ids": ["c3-11", "c3-14", "c3-32", "c3-33", "c3-42", "c3-60", "c3-141", "c3-162", "c3-227"]}, {"t": "法律的功能：保障權利、限制政府", "n": 7, "ids": ["c3-53", "c3-56", "c3-120", "c3-137", "c3-178", "c3-224", "c3-307"]}]}, {"id": "c3", "name": "權力分立與分權制衡", "n": 61, "level": "必考", "card": {"說明": "英國歷史學家艾克頓爵士（Lord Acton）提出名言：「<b>權力使人腐化，絕對的權力，絕對的腐化</b>」，指出掌權者若缺乏約束便容易產生私心與野心。為了避免國家權力集中於少數人手中導致專權，民主國家將統治權力分割給不同機關分別掌理。透過機關間各司其職且相互監督牽制，維持國家權力的平衡，達成保障人民權利的最終目的。", "關鍵名詞": "• <b>權力分立</b>：指國家將各種性質不同的統治職能加以分散，分別交由獨立機關執行的制度。<br>• <b>分權制衡</b>：指各政府機關在分工行使權力的基礎上，享有制約與監督彼此的職權，維持政局穩定與權力均衡。", "因果／影響": "採行權力分立能有效打破獨裁體制，防範統治者濫權侵害人權；然而各機關若缺乏妥善協調機制，亦可能在政策或預算審查時產生政黨對立與施政僵局，需仰賴健全的憲政程序化解。", "出處": "自修第 265～266 頁／講義第 30～31 頁（試題寶典評量第 22 頁、速讀秘笈第 3 頁）。", "標示": "講義與自修均列為「<b>必考重點</b>」，評量單標為「<b>核心素養題型</b>」。"}, "imgs": ["c4-map-budget"], "clusters": [{"t": "艾克頓：權力使人腐化", "n": 12, "ids": ["c3-19", "c3-48", "c3-61", "c3-116", "c3-136", "c3-148", "c3-192", "c3-194", "c3-234", "c3-246", "c3-300", "c3-301"]}, {"t": "分權制衡的實例（預算、覆議、不信任案）", "n": 24, "ids": ["c3-18", "c3-34", "c3-35", "c3-46", "c3-52", "c3-63", "c3-64", "c3-82", "c3-94", "c3-103", "c3-104", "c3-118", "c3-119", "c3-123", "c3-158", "c3-167", "c3-176", "c3-188", "c3-203", "c3-217", "c3-236", "c3-241", "c3-304", "c3-309"]}, {"t": "權力分立的目的", "n": 25, "ids": ["c3-5", "c3-22", "c3-26", "c3-41", "c3-65", "c3-84", "c3-100", "c3-131", "c3-133", "c3-135", "c3-139", "c3-144", "c3-147", "c3-172", "c3-184", "c3-190", "c3-206", "c3-207", "c3-211", "c3-223", "c3-228", "c3-303", "c3-310", "c3-316", "c3-322"]}]}, {"id": "c4", "name": "孟德斯鳩的三權分立", "n": 48, "level": "必考", "card": {"說明": "法國啟蒙思想家孟德斯鳩承襲英國學者洛克等人的分權思想，於其著作中正式倡導<b>三權分立</b>學說。他主張將國家權力畫分為<b>行政權</b>、<b>立法權</b>與<b>司法權</b>。其中立法權負責制定法律與審查預算，行政權負責執行政策，而超出黨派利益衝突之外的司法權則獨立審判，以法制衡行政與立法，防止任何單一機關專斷獨行。", "關鍵名詞": "• <b>三權分立</b>：將國家統治權畫分為行政、立法、司法三種權力，並交由三個獨立機關相互制衡的制度。<br>• <b>司法獨立</b>：指法院與司法人員依法獨立審判，不受行政機關、立法機關或政黨立場干涉的憲政原則。", "因果／影響": "三權分立奠定了當代西方民主憲政國家的主要制度架構（如美國）；行政機關受到國會的預算審查與法律約束，法院則能審理政府是否違法，確保國家公權力的合法運作。", "出處": "自修第 265 頁／講義第 31 頁（試題寶典評量第 22 頁、速讀秘笈第 3 頁）。", "標示": "講義與速讀秘笈標為「<b>重點分析</b>」，會考模擬考常設為「<b>精熟題</b>」。"}, "imgs": ["c3-map-powers"], "clusters": [{"t": "三權的分工：行政、立法、司法", "n": 36, "ids": ["c3-8", "c3-16", "c3-21", "c3-36", "c3-37", "c3-47", "c3-66", "c3-89", "c3-92", "c3-93", "c3-101", "c3-109", "c3-111", "c3-124", "c3-128", "c3-138", "c3-142", "c3-157", "c3-165", "c3-166", "c3-173", "c3-182", "c3-185", "c3-191", "c3-198", "c3-212", "c3-229", "c3-235", "c3-239", "c3-243", "c3-244", "c3-313", "c3-324", "c3-325", "c3-326", "c3-328"]}, {"t": "孟德斯鳩與三權分立", "n": 12, "ids": ["c3-6", "c3-20", "c3-97", "c3-113", "c3-121", "c3-168", "c3-214", "c3-225", "c3-226", "c3-302", "c3-306", "c3-323"]}]}, {"id": "c5", "name": "孫中山的五權分立", "n": 42, "level": "必考", "card": {"說明": "孫中山先生結合西方三權分立體制與我國歷史傳統特點，提出獨具特色的<b>五權分立</b>政治思想，做為我國中央政府體制的藍圖。他認為西方三權分立制度下，行政機關兼具用人與考選資格之權，容易產生<b>濫用私人</b>的流弊，故將「<b>考試權</b>」從行政權中獨立出來；同時，國會兼具立法與監督彈劾之權，容易導致<b>國會專制</b>，故特將「<b>監察權</b>」從立法權中獨立出來，以健全政府功能。", "關鍵名詞": "• <b>五權分立</b>：我國中央政府組織原則，將國家權力分為行政權、立法權、司法權、考試權、監察權五種，分別由五院行使。<br>• <b>考試權獨立</b>：為落實公正舉才、保障公務人員權益，將考選與銓敘權限自行政權抽離獨立的機制。<br>• <b>監察權獨立</b>：為防止議會專斷、監督違法失職公務員，將彈劾、糾舉與審計等監察權限獨立行使的體制。", "因果／影響": "五權分立使我國中央政府具備五院分工運作的特色架構；考試院獨立確保考選制度公平客觀，監察院獨立則加強對行政失職之彈劾與糾正，但也需要五院間更綿密的憲政互動以維持運作順暢。", "出處": "自修第 265 頁／講義第 31 頁（試題寶典評量第 22 頁、速讀秘笈第 3 頁）。", "標示": "講義與自修均列為「<b>必考／易混淆重點</b>」，隨堂評量單必考填空題。"}, "imgs": ["c3-map-powers"], "clusters": [{"t": "考試權獨立：避免濫用私人", "n": 30, "ids": ["c3-7", "c3-23", "c3-31", "c3-49", "c3-50", "c3-67", "c3-77", "c3-86", "c3-91", "c3-106", "c3-114", "c3-127", "c3-150", "c3-156", "c3-160", "c3-161", "c3-170", "c3-171", "c3-180", "c3-193", "c3-196", "c3-197", "c3-199", "c3-208", "c3-209", "c3-213", "c3-233", "c3-237", "c3-238", "c3-317"]}, {"t": "監察權獨立：避免國會專制", "n": 4, "ids": ["c3-90", "c3-126", "c3-218", "c3-319"]}, {"t": "五權分立的特色", "n": 8, "ids": ["c3-28", "c3-68", "c3-152", "c3-169", "c3-201", "c3-232", "c3-245", "c3-320"]}]}, {"id": "c2", "name": "權利與權力", "n": 32, "level": "必考", "card": {"說明": "<b>權利（Right）</b>與<b>權力（Power）</b>是法治國家的兩個運作軸心，兩者內涵截然不同。權利屬於私法與公法保障下的人民利益，人民享有要求國家或他人不予侵害的自主資格；權力則多指國家或政府機關所掌握的強制支配力量，政府以此維護社會秩序與公共利益。在民主法治國家中，政府行使權力必須嚴格受到《憲法》與法律的限制，絕對不得侵犯人民合法的基本權利。", "關鍵名詞": "• <b>權利（Right）</b>：指在法律保障之下，人民享有避免受到任意侵害並追求生活利益的合法權益。<br>• <b>權力（Power）</b>：指個人、團體或政府機關具有優勢資源，得以強制力量影響他人行為並執行特定事務的能力。<br>• <b>公權力</b>：指政府為維護社會秩序與公共利益，依法對人民產生拘束與處罰的強制力量。", "因果／影響": "明確釐清權利與權力的分際，能避免政府公權力無限擴張；若政府濫用公權力進行未經法律授權的搜查、拘捕或處罰，即會侵害人民受憲法保障的人身自由與各項基本權益。", "出處": "自修第 261 頁／講義第 29、32 頁（試題寶典評量第 21 頁、速讀秘笈第 3 頁）。", "標示": "講義標為「<b>延伸學習</b>」，試題寶典標為「<b>易錯精熟考點</b>」。"}, "imgs": [], "clusters": [{"t": "權力：政府的強制力量（公權力）", "n": 14, "ids": ["c3-12", "c3-24", "c3-27", "c3-59", "c3-70", "c3-74", "c3-112", "c3-134", "c3-143", "c3-174", "c3-179", "c3-187", "c3-205", "c3-230"]}, {"t": "權利 vs 權力 辨別", "n": 18, "ids": ["c3-4", "c3-45", "c3-51", "c3-57", "c3-88", "c3-107", "c3-145", "c3-146", "c3-151", "c3-153", "c3-163", "c3-189", "c3-202", "c3-216", "c3-222", "c3-315", "c3-318", "c3-321"]}]}, {"id": "c6", "name": "有限政府", "n": 22, "level": "常考", "card": {"說明": "有限政府是指政府的權力、規模與施政範圍都受到《憲法》與法律明文嚴格限制的國家體制。民主國家透過憲政規範與權力分立機制，確立政府只是人民受託管理公共事務的機關，絕非無所不能的萬能政府。國家機構必須在法定職權範圍內行使公權力，且隨時接受民意代表、司法裁判與社會輿論的監督，以防範公權力侵害人民合法權益。", "關鍵名詞": "• <b>有限政府</b>：指在權力、職能和規模上都受到《憲法》和法律嚴格約束與限制的政府。", "因果／影響": "建立有限政府能確保統治機關遵循憲政正當程序，達成保障人民生命、財產與自由的核心價值；相對地，缺乏法律約束的無限政府則極易演變為極權專制，人民的基本人權將蕩然無存。", "出處": "自修第 266 頁／講義第 31～32 頁（試題寶典評量第 22 頁、評量單第 6 回）。", "標示": "講義名詞 Q&amp;A 標為「<b>重要觀念</b>」，評量單列為「<b>必考名詞題</b>」。"}, "imgs": [], "clusters": [{"t": "有限政府與《憲法》", "n": 22, "ids": ["c3-9", "c3-17", "c3-30", "c3-38", "c3-62", "c3-99", "c3-110", "c3-117", "c3-122", "c3-129", "c3-130", "c3-132", "c3-140", "c3-159", "c3-164", "c3-210", "c3-215", "c3-220", "c3-231", "c3-305", "c3-314", "c3-327"]}]}], "questions": [{"id": "c3-1", "no": 1, "c": "c1", "src": "教學式講義第 30 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "馬克思：「在民主的國家，法律就是國王；在專制的國家，國王就是法律。」針對這段話的解讀，下列何者較不正確？", "o": ["專制國家是人治社會", "民主國家是法治社會", "人治社會中人民權利較有保障", "這段話可說明人治和法治的不同"], "a": 2, "e": "民主國家「法律就是國王」是法治，人民權利較有保障；專制國家是人治，人民權利較無保障。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-2", "no": 2, "c": "c1", "src": "教學式講義第 30 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "在法治國家，法律最主要的功能是下列何者？", "o": ["保障人民的權利", "限制人民的自由", "強化政府的權力", "作為統治者的工具"], "a": 0, "e": "法治社會中法律的主要功能是保障人民的權利，並限制政府的權力。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-3", "no": 3, "c": "c1", "src": "教學式講義第 30 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "幸福國由人民選出的代表制定法律，政府再依據法律向人民課徵所得稅，該國人民若未如期繳納將遭受處罰。根據上述判斷，下列關於幸福國的敘述何者正確？", "o": ["該國的法律是限制人民的工具", "法律會隨著統治者的想法改變", "該國人民可以預期法律的效果", "該國的法律只約束人民的行為"], "a": 2, "e": "法律由人民選出的代表制定，政府依法課稅，人民可預期法律的效果，是法治社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-4", "no": 4, "c": "c2", "src": "教學式講義第 30 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "右圖是我國政府對民眾的宣導，根據圖中內容判斷，下列相關敘述何者正確？", "o": ["政府有在演習中管制人民的權利", "警察有強制民眾配合演習的權力", "警察在進行管制時不需遵守法律", "管制措施凸顯我國屬於人治國家"], "a": 1, "e": "警察依法要求民眾配合演習管制，是政府行使權力；警察也必須依法行政。", "rep": false, "img": "c3-q4", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-5", "no": 5, "c": "c3", "src": "教學式講義第 32 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "權力分立的理論主張將國家的權力交由不同的機關去執行，其主要目的應為何者？", "o": ["防止人民叛變", "保障人民權利", "鞏固政府權力", "強化政府效能"], "a": 1, "e": "權力分立是將國家權力分散交由不同機關行使、彼此制衡，以防止權力濫用、保障人民權利。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-6", "no": 6, "c": "c4", "src": "教學式講義第 32 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "多數民主國家是依據何種理論，將中央政府畫分為行政、立法與司法三種機關？", "o": ["中央集權", "人治社會", "三權分立", "法治社會"], "a": 2, "e": "孟德斯鳩提出三權分立：行政權執行政策、立法權制定法律並監督行政、司法權超出黨派獨立審判。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-7", "no": 7, "c": "c5", "src": "教學式講義第 32 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "擁有職權獨立的考試機關與監察機關，是我國中央政府體制與其他民主國家不一樣的地方。會有上述差異，是因為我國採哪一理論建構中央政府體制？", "o": ["三權分立", "專制獨裁", "民主共和", "五權分立"], "a": 3, "e": "孫中山提出五權分立：將考試權從行政權獨立（避免濫用私人），監察權從立法權獨立（避免國會專制）。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-8", "no": 8, "c": "c4", "src": "教學式講義第 32 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "下列為一則新聞節錄，根據內容判斷，白胡掌管法國政府的哪一項權力？「2024 年 12 月初，法國的巴尼耶政府垮台，接任的新總理白胡必須在短時間內完成組織政府、說服國會通過預算案的艱鉅任務，維持法國政府順利運轉。」", "o": ["行政權", "立法權", "司法權", "監察權"], "a": 0, "e": "新總理組織政府、推動預算、維持政府運轉，掌管的是行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-9", "no": 9, "c": "c6", "src": "教學式講義第 32 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "「有限政府」是指在權力、職能和規模上，受到《憲法》和法律明文規範，並受社會監督、約束的政府。民主國家通常會以何種原則來建立「有限政府」？", "o": ["主權獨立", "中央集權", "政黨輪替", "權力分立"], "a": 3, "e": "有限政府的權力、職能和規模都受《憲法》與法律限制，透過權力分立達成。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-10", "no": 10, "c": "c1", "src": "教學式講義第 33 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "法國國王路易十四有句名言「朕即國家」，意思是皇帝擁有國家所有財產和權力，隨時可以剝奪臣民的任何東西。根據上述判斷，在路易十四統治下的法國應屬於下列何者？", "o": ["民主國家", "法治社會", "人治社會", "自由國家"], "a": 2, "e": "「朕即國家」表示統治者擁有一切權力、不受法律約束，是人治社會。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-11", "no": 11, "c": "c1", "src": "教學式講義第 33 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "依我國《憲法》規定，非經司法或警察機關依法定程序，不得逮捕、拘禁；而非依法定程序之逮捕、拘禁，人民得拒絕之。根據上述可知，我國法律最主要的功能應為下列何者？", "o": ["作為統治的工具", "約束人民的自由", "強化政府的權力", "保障人民的權利"], "a": 3, "e": "非依法定程序不得逮捕拘禁，顯示法律的主要功能是保障人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-12", "no": 12, "c": "c2", "src": "教學式講義第 33 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "新聞報導：「颱風天時常見民眾前往海邊觀浪、衝浪，若經執法人員勸導後，民眾仍在海邊逗留或從事活動，主管機關可依法對違規者開單處罰。」根據上述內容判斷，政府對違規者開罰的作法是根據下列何者？", "o": ["權力", "權利", "民主", "專制"], "a": 0, "e": "主管機關依法開單處罰，是政府行使公權力（權力）。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-13", "no": 13, "c": "c1", "src": "教學式講義第 33 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "根據法治社會的意涵判斷，法治社會最可能發生下列何種情況？", "o": ["統治者可以隨意徵稅", "人民可預見法律效果", "人民的言行不受任何約束", "法律隨統治者想法而改變"], "a": 1, "e": "法治社會中政府與人民都受法律約束，政府依法行政，人民可預期法律效果。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-14", "no": 14, "c": "c1", "src": "教學式講義第 34 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "我國警察執行路檢執勤時，須依據《警察職權行使法》的相關規定進行，且不能全面盤查所有通過車輛。根據上述內容判斷，下列何者最符合我國現況？", "o": ["人民須遵守法律但政府不用", "政府在執法上缺乏明確依據", "法律沒辦法保障人民的權利", "法律是用來限制政府的權力"], "a": 3, "e": "警察執勤須依《警察職權行使法》，表示法律用來限制政府權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-15", "no": 15, "c": "c1", "src": "教學式講義第 34 頁 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "表(一)是跨安統整人治社會與法治社會的比較，表中哪一個項目的內容有誤？\n表(一)：\n(甲)法律制定者：人治社會為「統治者」，法治社會為「人民選出的代表」\n(乙)法律目的：人治社會為「鞏固人民權利」，法治社會為「保障政府權力」\n(丙)法律約束力：人治社會為「法律只約束人民」，法治社會為「法律同時約束政府與人民」\n(丁)法律的變動：人治社會為「隨著統治者的想法而改變」，法治社會為「不會隨意變動」", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "人治社會的法律目的是鞏固「統治者」的權力，法治社會則是「限制政府權力、保障人民權利」，乙項寫錯了。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-16", "no": 16, "c": "c4", "src": "教學式講義第 34 頁 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "公民老師正在介紹三權分立的理論，下列何者最可能是老師用以輔助說明的示意圖？", "o": ["包含行政權、立法權、司法權", "包含考試權、立法權、行政權", "包含行政權、監察權、司法權", "包含行政權、立法權、監察權"], "a": 0, "e": "三權分立是行政權、立法權、司法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-17", "no": 17, "c": "c6", "src": "教學式講義第 34 頁 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "許多民主國家為維護人民的自由與基本權利，因此建構「有限政府」治理國家。下列關於「有限政府」的敘述何者正確？", "o": ["政府的權力集中在少數人手中", "政府的權力由國際組織所賦予", "政府的職權可隨統治者的想法變動", "政府的權力受《憲法》與法律規範"], "a": 3, "e": "有限政府的權力、職能和規模都受《憲法》與法律限制，透過權力分立達成。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-18", "no": 18, "c": "c3", "src": "教學式講義第 34 頁 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "在民主國家中，政府體制的「分權制衡」指的是下列何者？", "o": ["中央政府將行政職權下放給地方政府", "設立正、副首長分散權力，彼此制衡", "政府將權力畫分給不同機構，彼此相互制衡", "將考試、監察兩權從行政、司法兩權中分出"], "a": 2, "e": "分權制衡是政府將權力畫分給不同機構，彼此相互制衡。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-19", "no": 19, "c": "c3", "src": "教學式講義第 34 頁 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "英國歷史學家艾克頓爵士說過：「權力使人腐化，絕對的權力，絕對的腐化。」因此，現代國家的中央政府體制大多採何種原則設計？", "o": ["主權在民", "中央集權", "政黨輪替", "權力分立"], "a": 3, "e": "為避免權力集中而腐化，現代國家多以權力分立為原則。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-20", "no": 20, "c": "c4", "src": "教學式講義第 34 頁 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "中央政府權力分別歸屬於不同的政府部門，彼此互相制衡，難免會涉及政黨立場或利害得失的衝突，因此必須設立哪一機關，超出黨派、依法獨立行使職權？", "o": ["行政機關", "立法機關", "司法機關", "考試機關"], "a": 2, "e": "司法機關超出黨派、依法獨立行使職權，處理政黨立場或利益衝突。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-21", "no": 21, "c": "c4", "src": "教學式講義第 34 頁 第 12 題", "st": "講義", "ctx": "", "fig": "", "q": "為促進我國運動的發展，某政府機關於 2025 年初通過成立運動部的相關法律，使該部門的設立有了法源依據。上述「某政府機關」最可能掌握下列哪一種權力？", "o": ["行政權", "立法權", "監察權", "司法權"], "a": 1, "e": "通過成立運動部的法律，是立法機關行使立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-22", "no": 22, "c": "c3", "src": "教學式講義第 35 頁 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "「美國憲法之父」麥迪遜認為，掌握過大權力的人都不可以信任，因此他將口的理念放入《美國憲法》中，進而奠定了美國的憲政體制。上述的口應為相何種理念？", "o": ["依法行政", "主權在民", "權力分立", "民意政治"], "a": 2, "e": "麥迪遜不信任掌握過大權力的人，所以把權力分立的理念放入《美國憲法》。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-23", "no": 23, "c": "c5", "src": "教學式講義第 35 頁 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(一)為安安在某書中看到的內容，孫中山先生為了避免行政首長發生如圖中唐玄宗的錯誤，特意將何種權力從行政權中獨立出來？\n圖(一)文字：「唐玄宗晚年沉迷於享樂，又用人不當，重用口蜜腹劍的李林甫及楊國忠，最終導致安史之亂，使唐帝國盛況轉趨沒落。」", "o": ["考試權", "司法權", "監察權", "立法權"], "a": 0, "e": "為避免行政首長用人不當（如唐玄宗重用李林甫），孫中山將考試權從行政權獨立出來。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-24", "no": 24, "c": "c2", "src": "教學式講義第 35 頁 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "根據「權力」與「權利」的定義判斷，下列哪一則新聞標題與「權力」最相關？", "o": ["國考新制！國家考試的考生免用入場證", "違建套房出租，未限期改善遭強制拆除", "2025年元旦起，全民公費打流感疫苗", "反對山坡蓋遊戲場，地方民眾連署抗議"], "a": 1, "e": "違建遭政府強制拆除，是政府行使公權力；其他多屬人民享有的權利。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-25", "no": 25, "c": "c1", "src": "教學式講義第 35 頁 第 16 題", "st": "講義", "ctx": "", "fig": "", "q": "我國設有行政、立法、司法、考試、監察五院，其設立與職權皆明文規範在《憲法》與《憲法增修條文》中。根據上述，我國政治制度的設計，與下列哪一概念較無關聯？", "o": ["權力分立", "有限政府", "五權分立", "人治社會"], "a": 3, "e": "我國以《憲法》規範五院職權，屬權力分立、有限政府、五權分立，與人治無關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-26", "no": 26, "c": "c3", "src": "教學式講義第 35 頁 第 17 題", "st": "講義", "ctx": "", "fig": "", "q": "啟蒙時代的英國思想家洛克曾提出以下看法，根據內容判斷，洛克的看法與下列哪一概念最相符？「人們經由多數同意將權力委託政府，其終極目的是為維護社會公益，進而保障個人的生命、自由與財產。為確保政府的存在符合上述目的，政府中的不同職權必須由不同機關或人員行使，以避免權力過於集中。」", "o": ["人治社會", "權力分立", "威權體制", "依法行政"], "a": 1, "e": "洛克主張不同職權由不同機關行使、避免權力集中，就是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-27", "no": 27, "c": "c2", "src": "教學式講義第 35 頁 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(二)為小徹在影集中看到警察逮捕嫌疑犯的畫面，圖中警察對嫌犯說的話，其目的最可能為下列何者？", "o": ["彰顯政府公權力", "保障人民的權利", "凸顯該國屬於人治社會", "強調權力分立的重要性"], "a": 1, "e": "警察告知嫌犯有保持沉默、請律師等權利，目的是保障人民的權利。", "rep": false, "img": "c3-q27", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-28", "no": 28, "c": "c5", "src": "教學式講義第 35 頁 第 19 題", "st": "講義", "ctx": "", "fig": "", "q": "下列是哈囉國的交通部部長與其部屬的對話，根據對話可知，哈囉國的政府機關設計最可能呈現出何種現象？\n部長：「我兒子最近大學畢業，安排個職位給我兒子吧！明天我就叫他來報到。」\n部屬：「是的！我會安排個不錯的職位給令公子。」", "o": ["行政權兼考選權", "立法權兼司法權", "司法權兼行政權", "立法權兼行政權"], "a": 0, "e": "部長可直接安排兒子任職，表示行政機關同時掌握用人與考選資格的權力，容易濫用私人。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-29", "no": 29, "c": "c1", "src": "教學式講義第 36 頁 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "一位來自北韓的「脫北者」18 歲時逃出北韓，於 2015 年出書揭露人治國家的內幕和脫北經歷。根據上述判斷，下列哪一段文字最可能出現在她的書中？", "o": ["人民可以預期法律的效果", "法律由人民選出代表制定", "統治者依好惡規範人民服裝", "政府機關的施政受法律約束"], "a": 2, "e": "北韓是人治國家，統治者可依好惡規範人民（例如服裝）。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-30", "no": 30, "c": "c6", "src": "教學式講義第 36 頁 第 21 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(三)為我國中央政府總預算審查、執行與審核流程。圖中內容最符合下列哪一概念？", "o": ["有限政府", "民意政治", "政治責任", "主權在民"], "a": 0, "e": "預算由行政機關編列、立法機關審查、審計機關審核，政府權力受限制，是有限政府。", "rep": true, "img": "c3-q30", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-31", "no": 31, "c": "c5", "src": "教學式講義第 36 頁 第 22 題", "st": "講義", "ctx": "", "fig": "", "q": "阿亮要以「五權分立」為題進行課堂報告，下列哪一敘述最不可能出現在報告中？", "o": ["避免國家權力過度集中而侵害人民權利", "此一理論在西方民主國家被廣泛地運用", "考試權從行政權中獨立可避免濫用私人", "監察權從立法權中獨立可杜絕國會專制"], "a": 1, "e": "五權分立是我國獨有的制度，西方民主國家多採三權分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-32", "no": 32, "c": "c1", "src": "教學式講義第 36 頁 第 23 題", "st": "講義", "ctx": "", "fig": "", "q": "新聞報導：「某縣市發生冷氣機在施工過程中墜落砸死人的事件，民眾擔憂掛在建築物外牆的冷氣機可能潛在風險。有民意代表提出，應修法加強針對外牆附加掛冷氣的安全管理，讓廠商施工、政府管制有所依據。」上述新聞內容最能凸顯我國的哪一現狀？", "o": ["法律會朝令夕改", "政府須依法行政", "法律侵害人民權力", "法律保障政府權利"], "a": 1, "e": "修法讓廠商施工、政府管制有所依據，顯示政府須依法行政。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-33", "no": 33, "c": "c1", "src": "教學式講義第 36 頁 第 24 題", "st": "講義", "ctx": "", "fig": "", "q": "新聞報導：「一名老師在路上被員警攔下，認為她神情緊張，要求出示證件，但該名老師認為警察沒有正當理由而拒絕配合，雙方爆發衝突。最後老師被認定妨礙公務而遭上銬逮捕，事件曝光後引起社會輿論譁然。」以下是幾名網友討論上述新聞的留言，根據內容判斷，哪一位網友最可能是站在法治的角度闡述意見？", "o": ["甲：遇到警察盤查就應該接受，不乖乖配合只會惹禍上身", "乙：誰叫你神情緊張讓人懷疑，警察會想盤查也很合理", "丙：警察要求民眾出示證件，必須合乎法律規定，不能濫用職權", "丁：法律本來就是用來限制人民的工具，不然如何維持社會秩序"], "a": 2, "e": "丙認為警察要求出示證件須合乎法律規定，是法治的角度。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-34", "no": 34, "c": "c3", "src": "教學式講義第 36 頁 第 25 題", "st": "講義", "ctx": "", "fig": "", "q": "國際新聞：「美國總統日前簽署行政命令，取消美國的『出生公民權』，由於這項權利的法源為《美國憲法》第十四修正案，該行政命令因而遭提起違憲訴訟。聯邦法官認為該命令確實有違憲疑慮，因而發布為期 14 天的限制令，暫停此項行政命令的實施。」上述新聞最能凸顯美國政治的何種特色？", "o": ["中央集權", "政黨政治", "萬能政府", "分權制衡"], "a": 3, "e": "法官以行政命令違憲而暫停實施，是司法權制衡行政權，屬分權制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-35", "no": 35, "c": "c3", "src": "教學式講義第 36 頁 第 26 題", "st": "講義", "ctx": "", "fig": "", "q": "新聞報導：日前因人為疏失造成全臺數百萬戶大停電，立法院不分朝野為了追究責任，將請行政院院長提出專案報告。此外，在野黨立委認為近來行政團隊表現不佳，若專案報告無法切中要點、妥善檢討，將對行政院院長提出不信任案。根據我國政府機關間的互動關係判斷，上述內容主要符合下列何項概念？", "o": ["均權制度", "分權制衡", "主權在民", "地方自治"], "a": 1, "e": "立法院要求行政院院長報告並可提不信任案，是立法權制衡行政權。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-36", "no": 36, "c": "c4", "src": "教學式講義第 37 頁 第 27 題", "st": "講義", "ctx": "", "fig": "", "q": "有一本書上寫著：「如果立法權和行政權集中在同一人手中，自由便不能存在；如果司法權不和立法權、行政權分立，自由也不存在。……在土耳其帝國，這三項權力集中在『蘇丹』（統治者）一人身上，所以可怕的暴政控制著一切。」這樣的論述最可能是出於下列何人？", "o": ["但丁", "培根", "馬丁路德", "孟德斯鳩"], "a": 3, "e": "主張立法、行政、司法三權分立以保障自由，是孟德斯鳩的論述。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-37", "no": 37, "c": "c4", "src": "教學式講義第 37 頁 第 28 題", "st": "講義", "ctx": "美國第一屆總統華盛頓在擔任兩任總統後便放棄競選連任，往後的總統為表示敬意，皆只會連任一屆，直到小羅斯福擔任總統時才打破此一慣例。當時由於正值第二次世界大戰，美國為了維持政局穩定、全面備戰，由小羅斯福於 1933～1945 年連任了四屆總統。後來，美國國會於 1947 年通過《憲法》修正案，1951 年明文將美國總統任期限定為兩屆。現在多數民主國家也都會限制領導人的任期，例如：我國規定總統最多只能連任一屆，南韓則規定總統不可連任。相對的，也有些國家的領導人在取得政權後，則希望延長任期，例如：俄羅斯在 2000 年普丁首次當選總統後，於 2008 年修法，將總統任期由 4 年延長至 6 年；2020 年再度修法，取消了總統的任期制。", "fig": "", "q": "文中的美國國會，掌握的應是下列哪一種權力？", "o": ["行政權", "立法權", "司法權", "考試權"], "a": 1, "e": "美國國會制定法律、通過修憲案，掌握立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-38", "no": 38, "c": "c6", "src": "教學式講義第 37 頁 第 29 題", "st": "講義", "ctx": "美國第一屆總統華盛頓在擔任兩任總統後便放棄競選連任，往後的總統為表示敬意，皆只會連任一屆，直到小羅斯福擔任總統時才打破此一慣例。當時由於正值第二次世界大戰，美國為了維持政局穩定、全面備戰，由小羅斯福於 1933～1945 年連任了四屆總統。後來，美國國會於 1947 年通過《憲法》修正案，1951 年明文將美國總統任期限定為兩屆。現在多數民主國家也都會限制領導人的任期，例如：我國規定總統最多只能連任一屆，南韓則規定總統不可連任。相對的，也有些國家的領導人在取得政權後，則希望延長任期，例如：俄羅斯在 2000 年普丁首次當選總統後，於 2008 年修法，將總統任期由 4 年延長至 6 年；2020 年再度修法，取消了總統的任期制。", "fig": "", "q": "文中美國通過《憲法》修正案以限制總統任期，主要目的為下列何者？", "o": ["賦予領導者治理國家的權力", "鞏固政府的權力以強化統治", "限制政府的權力以保障人民權利", "透過權力分立避免權力過度集中"], "a": 2, "e": "限制總統任期是以法律限制政府的權力，保障人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-39", "no": 39, "c": "c1", "src": "教學式講義第 37 頁 第 30 題", "st": "講義", "ctx": "美國第一屆總統華盛頓在擔任兩任總統後便放棄競選連任，往後的總統為表示敬意，皆只會連任一屆，直到小羅斯福擔任總統時才打破此一慣例。當時由於正值第二次世界大戰，美國為了維持政局穩定、全面備戰，由小羅斯福於 1933～1945 年連任了四屆總統。後來，美國國會於 1947 年通過《憲法》修正案，1951 年明文將美國總統任期限定為兩屆。現在多數民主國家也都會限制領導人的任期，例如：我國規定總統最多只能連任一屆，南韓則規定總統不可連任。相對的，也有些國家的領導人在取得政權後，則希望延長任期，例如：俄羅斯在 2000 年普丁首次當選總統後，於 2008 年修法，將總統任期由 4 年延長至 6 年；2020 年再度修法，取消了總統的任期制。", "fig": "", "q": "根據上文內容判斷，現在的俄羅斯比較偏向下列何種社會？", "o": ["人治", "法治", "神治", "自治"], "a": 0, "e": "俄羅斯領導人修法延長、取消任期限制，偏向人治。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-40", "no": 40, "c": "c1", "src": "教學式講義第 37 頁 第 31 題", "st": "講義", "ctx": "王莽是中國歷史上一位備受爭議的皇帝，他憑藉人民的擁戴登上皇帝寶座，以和平的方式篡奪了西漢的政權，開創「新朝」。王莽在位期間，進行了一系列的改革措施，史稱「王莽改制」，其內容雖富有理想，但與當時的社會現實嚴重脫節，加上統治者專權獨斷、聽不進旁人建議，時常朝令夕改，使百姓和官員無所適從，深受其害。最終，王莽僅僅做了 16 年的皇帝，新朝就在各地風起雲湧的暴力反抗中走向滅亡。", "fig": "", "q": "根據上文判斷，王莽治理下的新朝最可能具有下列何種特色？", "o": ["法律限制統治者權力", "法律由民意代表制定", "統治者以法律限制人民", "人民可預期法律的效果"], "a": 2, "e": "王莽專權獨斷、朝令夕改，是人治，統治者以法律限制人民。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-41", "no": 41, "c": "c3", "src": "教學式講義第 37 頁 第 32 題", "st": "講義", "ctx": "王莽是中國歷史上一位備受爭議的皇帝，他憑藉人民的擁戴登上皇帝寶座，以和平的方式篡奪了西漢的政權，開創「新朝」。王莽在位期間，進行了一系列的改革措施，史稱「王莽改制」，其內容雖富有理想，但與當時的社會現實嚴重脫節，加上統治者專權獨斷、聽不進旁人建議，時常朝令夕改，使百姓和官員無所適從，深受其害。最終，王莽僅僅做了 16 年的皇帝，新朝就在各地風起雲湧的暴力反抗中走向滅亡。", "fig": "", "q": "若要改善文中王莽治理的缺失，最適合理用下列哪一方式？", "o": ["以嚴刑峻法鞏固統治者的權力", "依權力分立原則分散政府權力", "取消所有法律，放任人民自治", "將政府權力集中在同一人手中"], "a": 1, "e": "要改善專權獨斷，應依權力分立原則分散政府權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-42", "no": 42, "c": "c1", "src": "教學式講義第 49 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "下列分別是四個國家的警員在執法時所說的話，根據內容判斷，哪一位警員所在的國家屬於法治社會的國家？\n警員甲：「司法機關搜索民宅，必須出示搜索票。」\n警員乙：「為維護治安，每一位警員可隨時隨地執行臨檢盤查。」\n警員丙：「只要是犯罪嫌疑人，任何一個政府機關皆可予以逮捕。」\n警員丁：「進行拘提時不須告知理由，避免案情外洩。」", "o": ["警員甲", "警員乙", "警員丙", "警員丁"], "a": 0, "e": "警員甲表示搜索民宅須出示搜索票，政府依法行政，是法治國家。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-43", "no": 43, "c": "c1", "src": "教學式講義第 49 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "國際新聞：「北韓政府為了對抗南韓文化入侵，屢屢修法防堵，2020 年更直接推出《反動思想文化排斥法》，只要被發現散布或是觀看南韓影像、書籍，都要被判刑。」上述國家的狀況在現今的我國不會發生，這是因為我國的法律可發揮何種功能？", "o": ["作為統治的工具", "約束人民的自由", "強化政府的權力", "保障人民的權利"], "a": 3, "e": "我國是法治國家，法律保障人民的言論、表現自由等權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-44", "no": 44, "c": "c1", "src": "教學式講義第 49 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "亞里斯多德在其著作中提到：「與其讓公民中的一人統治，不如讓法律統治。」由此可知，下列何者最符合亞里斯多德的理念？", "o": ["統治者權力凌駕法律之上", "統治者可以自行變更法律", "以法律限制統治者的權力", "法律的執行依統治者喜好"], "a": 2, "e": "讓法律統治而非一人統治，就是以法律限制統治者的權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-45", "no": 45, "c": "c2", "src": "教學式講義第 49 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "老師在課堂上請同學舉出有關「權力」與「權利」的例子，下列何人舉例的內容與其他三者不同？", "o": ["小明：我有權在網路發表自己的意見", "小文：犯罪被害人有權爭取合理賠償", "小美：老師有權制止擾亂秩序的同學", "小玉：滿 18 歲的國民有權投下公投票"], "a": 2, "e": "小美說老師有權制止擾亂秩序的同學，是「權力」；其他三人說的是人民的「權利」。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-46", "no": 46, "c": "c3", "src": "教學式講義第 50 頁 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "以下為立法院網站部分介紹，文中內容凸顯我國中央政府的哪一特色？「預算為政府施政之根本，審查、議決預算案，是立法院監督政府施政的最佳途徑。行政院於會計年度開始 4 個月前，應將下年度總預算案提出於立法院審議；立法院應於會計年度開始 1 個月前議決；並於會計年度開始 15 日前由總統公布。」", "o": ["分權制衡", "依法行政", "三權分立", "政黨政治"], "a": 0, "e": "行政院提出預算、立法院議決、總統公布，各機關分工相互制衡，凸顯分權制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-47", "no": 47, "c": "c4", "src": "教學式講義第 50 頁 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "阿德在課堂報告中，以圖(四)介紹某國中央政府體制。根據圖中內容判斷，在阿德的報告中最不可能出現下列何項內容？", "o": ["藉此防止政府濫用權力", "透過分散權力相互制衡", "將監察權自立法權中獨立出來", "政府權力分別由不同機關執行"], "a": 2, "e": "圖中是總統、國會、法院的三權分立體制，不會提到將監察權獨立（那是五權分立）。", "rep": false, "img": "c3-q47", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-48", "no": 48, "c": "c3", "src": "教學式講義第 50 頁 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "英國歷史學家艾克頓爵士在其著作中提到：「權力使人腐化，絕對的權力，絕對的腐化。」為避免掌權者的野心與貪婪，導致人民權利遭受侵害，現代國家對於政府體制的設計，大多會以下列何者為原則？", "o": ["責任政治", "專權政治", "權力分立", "政黨輪替"], "a": 2, "e": "為避免權力集中而腐化，政府體制多以權力分立為原則。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-49", "no": 49, "c": "c5", "src": "教學式講義第 50 頁 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "我國現行的中央政府體制，是依據孫中山提出的獨特見解所建立。他認為我國文化中有偏重人際關係的傾向，因此認為「某兩權」若不能獨立運作，那麼一定會發生以私害公的弊端。上述「某兩權」應是指下列何者？", "o": ["行政權、立法權", "立法權、司法權", "行政權、考試權", "考試權、監察權"], "a": 3, "e": "孫中山認為考試權、監察權若不能獨立，會以私害公。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-50", "no": 50, "c": "c5", "src": "教學式講義第 51 頁 第 17 題", "st": "講義", "ctx": "", "fig": "", "q": "以下是一則新聞，根據文中考試委員的回應，考試權獨立應有何優點？「2019 年，立法院三讀通過《考試院組織法》，縮減考試委員名額及任期，將考試委員人數自原有的 19 人改為 7 至 9 人；任期則由 6 年縮短為 4 年。對此，有考試委員回應，此變動恐影響考試院的職權行使，而考試權獨立，則有助維持權力分立的體制。」", "o": ["避免司法權無力行使", "避免有限政府的無能", "避免立法院專制濫權", "避免行政院濫用私人"], "a": 3, "e": "考試權獨立可避免行政機關濫用私人，維持權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-51", "no": 51, "c": "c2", "src": "教學式講義第 51 頁 第 19 題", "st": "講義", "ctx": "", "fig": "", "q": "擔任公務人員的小可被指控貪汙，辦公室因而遭到警察搜索。關於上述情境，下列敘述何者最適當？", "o": ["若小可貪汙屬實，司法院可對他提出彈劾", "警察在搜索過程中的行為皆受到法律約束", "小可有權力拒絕無搜索票的警察進入辦公室", "持有搜索票的警察有權利搜索小可的辦公室"], "a": 1, "e": "法治社會中，警察搜索也必須依法進行，行為受法律約束。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-52", "no": 52, "c": "c3", "src": "教學式講義第 52 頁 第 21 題", "st": "講義", "ctx": "立法院通過 114 年度中央政府總預算案，總預算歲出 3 兆 1,324 億寫下史上新高，而刪減數 2,075 億也創下新高，占總預算的 6.64%。行政院表示，根據主計總處分析，立法院相關說明與通案刪減數額的部分內容有所落差，且部分提案之刪減數已超過原本編列的預算，顯示本預算案的審議尚有待釐清之處。行政院認為此預算案窒礙難行，考慮依《憲法》與《憲法增修條文》之規定尋求救濟。", "fig": "", "q": "根據上文中政府機關的互動判斷，我國中央政府體制的設計是以下列何者為原則？\n題組材料摘述：「立法院通過 114 年度中央政府總預算案……行政院認為此預算案窒礙難行，考慮依《憲法》與《憲法增修條文》之規定尋求救濟。」", "o": ["政黨輪替", "責任政治", "主權在民", "分權制衡"], "a": 3, "e": "行政院對立法院通過的預算可提出覆議，顯示我國以分權制衡為原則。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-53", "no": 53, "c": "c1", "src": "評量單第 5 回 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "我國屬於法治社會，法律最主要的功能應為下列何者？", "o": ["作為統治的工具", "約束人民的自由", "強化政府的權力", "保障人民的權利"], "a": 3, "e": "法治社會中法律的主要功能是保障人民的權利，並限制政府的權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-54", "no": 54, "c": "c1", "src": "評量單第 5 回 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "「政府的施政作為必須依循法律，並受到法律的約束」，此為下列何者的內涵？", "o": ["法治社會", "君主專制", "法律位階", "人治社會"], "a": 0, "e": "政府施政須依循法律並受法律約束，是法治社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-55", "no": 55, "c": "c1", "src": "評量單第 5 回 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "在法治的社會，為了保障人民的權利，通常會採取何種方式？", "o": ["人民擁有絕對的自由", "廢除所有的王室象徵", "以法律限制政府的權力", "人民選出聽話的統治者"], "a": 2, "e": "法治社會以法律限制政府的權力來保障人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-56", "no": 56, "c": "c1", "src": "評量單第 5 回 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "夢想國是一個法治社會，下列哪一種情形最有可能出現在夢想國？", "o": ["只有人民受到法律的約束", "由人民選出代表制定法律", "國家可以限制人民的自由", "政府可以隨意向人民徵稅"], "a": 1, "e": "法治社會中政府與人民都受法律約束，政府依法行政，人民可預期法律效果。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-57", "no": 57, "c": "c2", "src": "評量單第 5 回 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "以下為阿德的課堂筆記，根據內容判斷，(甲)、(乙)依序分別為下列何者？\n(甲)：指個人或團體以強制的力量影響他人行為，並有能力執行某些事務。\n(乙)：在法律的保障之下，人民有避免受到任意侵害且享有追求某種利益的權益。", "o": ["權利、權力", "權力、權利", "權力、主權", "主權、公權力"], "a": 1, "e": "甲是以強制力量影響他人行為的「權力」；乙是受法律保障的「權利」。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-58", "no": 58, "c": "c1", "src": "評量單第 5 回 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "風之國的統治者說：「我說的話就是法律，人民的房子就是我的房子。」由上述可知，風之國應屬於下列何者？", "o": ["民主社會", "法治社會", "人治社會", "自由社會"], "a": 2, "e": "統治者的話就是法律，可任意侵害人民財產，是人治社會。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-59", "no": 59, "c": "c2", "src": "評量單第 5 回 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "元旦連假期間，警政署進行為期 3 天酒駕全國大執法，加強擴大酒駕臨檢，請民眾依法配合酒駕臨檢。上述政府要求民眾配合，是憑藉下列何者？", "o": ["權力", "權利", "民主", "專制"], "a": 0, "e": "政府依法要求民眾配合臨檢，憑藉的是權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-60", "no": 60, "c": "c1", "src": "評量單第 5 回 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "衛生局派員稽查某餐廳，查出多項衛生缺失，依《食品安全衛生管理法》開罰，並責令業者限期改善。上述衛生局的作法最符合法治社會的何種原則？", "o": ["法律規定須與時俱進", "政府執法有明確依據", "人民可自行制定法律", "法律內容須簡潔扼要"], "a": 1, "e": "衛生局依《食品安全衛生管理法》開罰，表示政府執法有明確依據。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-61", "no": 61, "c": "c3", "src": "評量單第 6 回 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "英國歷史學家艾克頓爵士的名言：「權力使人腐化，絕對的權力，絕對的腐化。」上述這句話的意思與下列何者比較接近？", "o": ["政府權力集中才能有效統治", "權力不能集中在少數人手中", "人民不適合擁有絕對的權力", "政府的權力比人民的權力大"], "a": 1, "e": "艾克頓的名言表示權力不能集中在少數人手中，以免被濫用。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-62", "no": 62, "c": "c6", "src": "評量單第 6 回 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "為了防止政府濫權，維護人民的自由與權利，因此民主國家應建立何種政府？", "o": ["有限政府", "萬能政府", "聯邦政府", "共和政府"], "a": 0, "e": "有限政府的權力受法律限制，可防止政府濫權。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-63", "no": 63, "c": "c3", "src": "評量單第 6 回 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "為落實保障人民基本權利的核心價值，我國以《憲法》及《憲法增修條文》規範政府的主要職權，將政府的權力畫分給不同的機構，使其相互制衡。上述設計符合下列何種理論的精神？", "o": ["政黨輪替", "人治社會", "權力分立", "依法行政"], "a": 2, "e": "將政府權力畫分給不同機構相互制衡，是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-64", "no": 64, "c": "c3", "src": "評量單第 6 回 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "民主國家會將統治者的權力分散，並建立一套讓權力相互制衡的政治制度。上述作法的主要目的應為下列何者？", "o": ["維護國家主權", "落實政黨政治", "集中政府權力", "防止權力濫用"], "a": 3, "e": "權力分散並相互制衡，主要目的是防止權力濫用。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-65", "no": 65, "c": "c3", "src": "評量單第 6 回 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "現代許多國家的政府設計，會將各種功能的權力加以分散，交由不同的機關執行。上述設計的主要核心價值應為下列何者？", "o": ["防止人民專制", "建構人治社會", "提升政府運作效率", "保障人民基本權利"], "a": 3, "e": "權力分立的核心價值是保障人民基本權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-66", "no": 66, "c": "c4", "src": "評量單第 6 回 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "孟德斯鳩認為，政府應有超出黨派且能獨立行使的權力，當權力相互制衡，有涉及政黨立場或利害得失的衝突時，該權力便能介入。上述權力應是指下列何者？", "o": ["行政權", "立法權", "司法權", "監察權"], "a": 2, "e": "孟德斯鳩認為司法權應超出黨派、獨立行使，以處理衝突。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-67", "no": 67, "c": "c5", "src": "評量單第 6 回 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "三權分立理論中，行政部門既有用人之權，又有決定資格之權，容易產生濫用私人的缺點，因此孫中山先生認為應該如何改善？", "o": ["將監察權從司法權獨立出來", "將考試權從行政權獨立出來", "將監察權從立法權獨立出來", "將考試權從司法權獨立出來"], "a": 1, "e": "為避免行政部門濫用私人，孫中山將考試權從行政權獨立出來。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-68", "no": 68, "c": "c5", "src": "評量單第 6 回 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "右圖的政治體制是何人所提出的理論？", "o": ["華盛頓", "孫中山", "孟德斯鳩", "艾克頓爵士"], "a": 1, "e": "行政、立法、司法、考試、監察五權分立，是孫中山提出的理論。", "rep": false, "img": "c3-q68", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-69", "no": 69, "c": "c1", "src": "試題寶典評量第 23 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "在何種社會中，法律是統治者用來限制人民的工具？", "o": ["法治社會", "民主社會", "人治社會", "工業社會"], "a": 2, "e": "人治社會中統治者的意思就是法律，法律是限制人民的工具，統治者不受法律約束。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-70", "no": 70, "c": "c2", "src": "試題寶典評量第 23 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "「權利」與「權力」的定義完全不同，若要舉例說明「權力」，下列哪一項最適切？", "o": ["隱私權不受侵害", "男女都有繼承權", "員工可拒絕加班", "警察依法開罰單"], "a": 3, "e": "警察依法開罰單是政府行使權力；其他都是人民的權利。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-71", "no": 71, "c": "c1", "src": "試題寶典評量第 23 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "有關人治社會的敘述，下列何者正確？", "o": ["統治者不需要遵守法律", "君主權力受到法律的約束", "政府機關執法有明確的依據", "法律可以保障人民的權利"], "a": 0, "e": "人治社會中統治者的意思就是法律，法律是限制人民的工具，統治者不受法律約束。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-72", "no": 72, "c": "c1", "src": "試題寶典評量第 23 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "在某個國家，總統可以隨意修改法律，甚至能夠決定誰應該接受審判或獲得特權，法院的判決往往取決於領導人的個人意志，而非法律規定。上述國家較符合下列何種特徵？", "o": ["法治國家——強調法律至上，任何人都必須遵守法律", "人治國家——由個人權力決定國家運作，法律可被領導者隨意更改", "民主國家——人民有權透過選舉決定法律", "福利國家——政府以公共利益為優先"], "a": 1, "e": "總統可隨意修法、決定審判，法院判決取決於領導人意志，是人治國家。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-73", "no": 73, "c": "c1", "src": "試題寶典評量第 23 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "某國家最近通過一項新法，規定政府官員必須公開財產，並接受獨立機構的監督，違法者將依法懲處，不論其職位高低。這種作法符合下列何種國家制度？", "o": ["人治國家", "威權國家", "法治國家", "獨裁國家"], "a": 2, "e": "官員公開財產、受監督、違法依法懲處，不論職位高低，是法治國家。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-74", "no": 74, "c": "c2", "src": "試題寶典評量第 23 頁 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "關於「權力」與「權利」的概念，下列何者正確？", "o": ["人民的權利來自政府授予，而政府的權力則是天生擁有的", "政府為維護社會秩序，對違法者有開罰的公權力", "人民沒有拒絕警察非法拘禁的權利", "權力與權利沒有關聯，政府不需要考慮人民的權利"], "a": 1, "e": "政府為維護秩序可依法開罰，是公權力；人民的權利是法律保障的，不是政府授予。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-75", "no": 75, "c": "c1", "src": "試題寶典評量第 23 頁 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "關於人治與法治，下列何者符合「法治國家」的精神？", "o": ["統治者可依個人意願決定法律的適用範圍", "政府與人民都必須受法律約束，依法行政", "法律僅適用於人民，政府有權不受法律限制", "法律的主要目的是讓統治者維持政權"], "a": 1, "e": "法治社會中政府與人民都受法律約束，政府依法行政，人民可預期法律效果。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-76", "no": 76, "c": "c1", "src": "試題寶典評量第 23 頁 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "下列何者為人治國家可能出現的現象？", "o": ["統治者可隨意修改法律，以符合自身利益", "法律是由人民選出的代表制定，以保護公民權利", "政府必須依法行政，不能任意侵犯人民的自由", "司法機關能獨立審理案件，不受政府干預"], "a": 0, "e": "統治者可隨意修改法律以符合自身利益，是人治國家的現象。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-77", "no": 77, "c": "c5", "src": "試題寶典評量第 23 頁 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "我國中央政府的分權方式採取孫中山先生提出的「五權分立」理論，為了杜絕國會專制的缺陷，而將哪一權力獨立出來？", "o": ["考試權", "司法權", "行政權", "監察權"], "a": 3, "e": "為杜絕國會專制，孫中山將監察權從立法權獨立出來。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-78", "no": 78, "c": "c1", "src": "試題寶典評量第 25 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "在法治社會中，人民與政府都必須受到法律的約束，藉此保障人民的權利，以及限制政府的權力。下列何者符合上述情況？", "o": ["雇主依照自己心情決定員工每天上班時間", "警察機關須持有搜索票才能搜查民宅", "政府遇到抗議人士便直接逮捕入獄", "統治者修改任期改成無限期連任"], "a": 1, "e": "警察須有搜索票才能搜查民宅，政府受法律約束，人民權利受保障。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-79", "no": 79, "c": "c1", "src": "試題寶典評量第 25 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "人治與法治是兩種不同的治理社會模式，表(一)有關人治社會與法治社會的比較，其中何項正確？", "o": ["國家領導者權力：人治為「受法律約束」，法治為「不受限制」", "人民權利：人治為「無法受到保障」，法治為「受法律保障」", "法律的修改：人治為「有一定程序」，法治為「隨統治者改變」", "法律的拘束力：人治為「與人民均需遵守法律規定」，法治為「根據自己好惡統治人民」"], "a": 1, "e": "人治社會人民權利無法受到保障，法治社會人民權利受法律保障；其他三項人治、法治寫反了。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-80", "no": 80, "c": "c1", "src": "試題寶典評量第 25 頁 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "歷史電視劇中常可看到官員說著「君要臣死，臣不得不死」的場面，在沒有任何制度保障可言的社會中，可能會出現下列何種情況？", "o": ["法律充分保障人民的權利", "統治者憑自己的好惡來統治人民", "政府所有作為須依法行政", "政府權力受到法律約束"], "a": 1, "e": "「君要臣死，臣不得不死」表示統治者憑好惡統治人民，是人治。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-81", "no": 81, "c": "c1", "src": "試題寶典評量第 25 頁 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "李姓男子去某國拜訪朋友，卻被該國警察任意逮捕、拘禁，在「被消失」177 天後，除了當庭認罪外，還被以「顛覆國家政權罪」重判五年。這種情況有可能會發生在何種國家？", "o": ["民主國家", "自由國家", "法治國家", "人治國家"], "a": 3, "e": "警察任意逮捕、拘禁人民，是人治國家才會發生的事。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-82", "no": 82, "c": "c3", "src": "試題寶典評量第 25 頁 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(一)是我國中央政府總預算的行政流程，此流程可以顯現我國政府運作符合何種憲政精神？", "o": ["權力分立", "民意政治", "主權在民", "人治政治"], "a": 0, "e": "預算由行政機關編列、立法機關審查、監察院審計部審核，國家權力畫分給不同機關，符合權力分立。", "rep": true, "img": "c3-q82", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-83", "no": 83, "c": "c1", "src": "試題寶典評量第 25 頁 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "我國《社會救助法》明定低收申請家戶需要有「實際的居住地」，以避免「籍在人不在」，並透過實地訪查確認貧困狀態，才能通過資格審核。這樣嚴格的審核方式符合何種社會的作法？", "o": ["人治社會", "獨裁社會", "專制社會", "法治社會"], "a": 3, "e": "政府依《社會救助法》嚴格依法審核，符合法治社會依法行政的作法。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-84", "no": 84, "c": "c3", "src": "試題寶典評量第 26 頁 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(二)是老師於課堂上書寫於黑板上的重點，由內容判斷，老師正在說明何種概念？", "o": ["無限政府", "主權在民", "權力分立", "法治政治"], "a": 2, "e": "將權力分散、避免專權、保持權力平衡，是權力分立。", "rep": false, "img": "c3-q84", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-85", "no": 85, "c": "c1", "src": "試題寶典評量第 26 頁 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "中世紀的西歐出現多個由領主管轄的「莊園」，領主有權力分封土地，制定一套屬於自己莊園內的規範，並保護莊園內的人民；人民則依照領主的規定服勞役或繳稅。上文中的「莊園」較偏向下列何種社會？", "o": ["人治社會", "法治社會", "民主社會", "人權社會"], "a": 0, "e": "領主可自訂規範、人民依領主規定服勞役，偏向人治社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-86", "no": 86, "c": "c5", "src": "試題寶典評量第 26 頁 第 12 題", "st": "講義", "ctx": "", "fig": "", "q": "曾有部分政黨提出修憲，將我國《憲法》中現有的五權分立，變成三權分立，以符合政治現實邏輯。表(二)是這兩種分權的比較，其中哪一項正確？", "o": ["三權分立：主要目的是限制人民權利；五權分立：主要目的是擴張政府權力", "三權分立：分行政、立法、監察權三權；五權分立：分行政、立法、司法、考試、監察五權", "三權分立：孟德斯鳩提出；五權分立：孫中山的理論", "三權分立：立法權依法獨立行使職權，監督行政權；五權分立：將考試權從監察權獨立出來，避免濫用私人"], "a": 2, "e": "三權分立由孟德斯鳩提出，五權分立是孫中山的理論；其他項都寫錯了。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-87", "no": 87, "c": "c1", "src": "試題寶典評量第 26 頁 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "在人治社會中，法律並不被視為最高的權威，領袖的個人意志可能會凌駕於法律之上。下列何者最符合這種情況？", "o": ["立法院院會依法定期開會開議", "領袖根據個人判斷決定是否遵守法律", "所有政策都經過民主程序產生", "每個人都能平等參與選舉"], "a": 1, "e": "領袖依個人判斷決定是否守法，是人治社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-88", "no": 88, "c": "c2", "src": "試題寶典評量第 26 頁 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "「權利」通常指的是個人根據法律擁有的自由與保障，而「權力」則是指對他人行為的控制能力。假如一個國家的政府過於強大，並且能夠不經法律約束地行使權力，會對國家的法律體系造成什麼影響？", "o": ["法律能夠充分保障所有人的權利，並且不用擔心政府濫權", "政府不經約束會使得法律無法有效保護人民權利，導致社會不公平", "公民的權利會得到更強的保護，因為政府有足夠的權力來維護秩序", "社會變得更加穩定，因為政府權力不受法律約束，能迅速處理問題"], "a": 1, "e": "政府權力不受法律約束，法律就無法保護人民權利，社會會不公平。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-89", "no": 89, "c": "c4", "src": "試題寶典評量第 26 頁 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "三權分立是民主國家最重要的基礎，有關三權分立的敘述，下列何者錯誤？", "o": ["司法權與立法權相互制衡", "行政機關掌握行政權，負責執行政策", "國會掌握立法權，負責制定法律、監督行政機關", "司法權依據法律獨立行使職權，以制衡行政與立法機關"], "a": 0, "e": "三權分立中立法權主要制衡行政權（審查預算、監督行政），題目說法錯誤；司法權則依法獨立審判。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-90", "no": 90, "c": "c5", "src": "試題寶典評量第 27 頁 第 16 題", "st": "講義", "ctx": "", "fig": "", "q": "同學們在課堂上針對「五權分立」進行討論，其中哪一位同學所說的內容出現錯誤？", "o": ["小文：「為我國所採行獨具特色的政治制度。」", "小華：「是孫中山先生提出的理論。」", "小智：「監察權從立法權獨立出來運作。」", "小強：「是我國地方政府體制。」"], "a": 3, "e": "五權分立是我國中央政府體制，不是地方政府體制。", "rep": false, "img": "c3-q90", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-91", "no": 91, "c": "c5", "src": "試題寶典評量第 27 頁 第 17 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(三)是某篇社論的部分內容，文中所謂獨立行使的權力是指下列何者？", "o": ["考試權", "監察權", "司法權", "立法權"], "a": 0, "e": "避免人事權被操控、任用私人，指的是考試權獨立。", "rep": false, "img": "c3-q91", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-92", "no": 92, "c": "c4", "src": "試題寶典評量第 27 頁 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "針對某地方政府收買記者一案，監察院全數通過彈劾案，懲戒法院判決出爐。監委指出，新聞媒體為獨立於現代民主法治國家立法、司法及行政三權分立之外的第四權，補充人民監督政府之不足，擔任監督政府濫用權力，避免腐敗的關鍵性角色，為不可或缺的憲政制度之一，並且為《憲法》第 11 條保障言論自由所明定。上文畫線處所描述的內容可補充三權分立中的哪一權？", "o": ["行政權", "司法權", "立法權", "考試權"], "a": 2, "e": "監督政府、避免濫權的功能，可補充三權分立中立法權（國會）監督行政的角色。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-93", "no": 93, "c": "c4", "src": "試題寶典評量第 27 頁 第 19 題", "st": "講義", "ctx": "", "fig": "", "q": "法國思想家孟德斯鳩提出「三權分立」學說，以確保各機關能夠互相制衡，防止權力過度集中。假設某國實施三權分立制度，但行政機關的領導人能夠直接修改法律，並且立法機關的決議必須由行政機關同意才能生效，而法院的判決還需要獲得總統批准才能執行。這個國家可能出現了哪種問題？", "o": ["行政機關的權力過大，破壞權力分立的原則", "立法機關的權力擴張，導致行政機關無法有效施政", "司法機關的權力過大，導致行政與立法機關無法運作", "權力平衡良好，三權分立的制度運作正常"], "a": 0, "e": "行政機關可直接修法、控制立法與司法，權力過大，破壞權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-94", "no": 94, "c": "c3", "src": "試題寶典評量第 27 頁 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "新聞報導：日前因人為疏失造成全臺數百萬戶大停電，立法院不分朝野為了追究責任，將請行政院院長提出專案報告。此外，在野黨立委認為近來行政團隊表現不佳，若專案報告無法切中要點、妥善檢討，將對行政院院長提出不信任案。根據我國政府機關間的互動關係判斷，上述內容主要符合下列何項概念？", "o": ["均權制度", "分權制衡", "主權在民", "地方自治"], "a": 1, "e": "立法院要求行政院院長報告並可提不信任案，是立法權制衡行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-95", "no": 95, "c": "c1", "src": "試題寶典評量第 28 頁 第 1 題", "st": "講義", "ctx": "在某個國家，最高領袖阿隆總是強調：「我就是法律。」他制定了許多規則，但人民發現，這些規則的執行方式因人而異。例如：一位普通市民因違反宵禁被關進監獄，而政府高官即使做了相同的事，卻毫髮無傷。有人開始質疑這個國家的法律公平性。後來，一群知識分子開始倡導改革，他們要求制定明確的法律，讓政府官員和人民都必須遵守，並建立一個權力分立的制度，以避免權力集中在領袖一人手中。有學者提出，要讓行政、立法、司法三個機關各司其職，互相制衡，確保政府運作公平。", "fig": "", "q": "關於阿隆的統治方式，下列何者最符合他的國家體制？", "o": ["三權分立，確保行政、立法、司法彼此制衡", "五權分立，讓監察權與考試權維護公平正義", "人治國家，法律的執行取決於統治者的意志", "法治國家，所有人都受到法律平等對待"], "a": 2, "e": "阿隆說「我就是法律」、規則因人而異，是人治國家。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-96", "no": 96, "c": "c1", "src": "試題寶典評量第 28 頁 第 2 題", "st": "講義", "ctx": "在某個國家，最高領袖阿隆總是強調：「我就是法律。」他制定了許多規則，但人民發現，這些規則的執行方式因人而異。例如：一位普通市民因違反宵禁被關進監獄，而政府高官即使做了相同的事，卻毫髮無傷。有人開始質疑這個國家的法律公平性。後來，一群知識分子開始倡導改革，他們要求制定明確的法律，讓政府官員和人民都必須遵守，並建立一個權力分立的制度，以避免權力集中在領袖一人手中。有學者提出，要讓行政、立法、司法三個機關各司其職，互相制衡，確保政府運作公平。", "fig": "", "q": "文中知識分子主張的改革方向，最符合哪一種國家治理的方式？", "o": ["法治國家，政府應依法行政，保障人民權利", "人治國家，領袖應該有最終決策權，不受法律約束", "君主專制，統治者的決定即為最高法律", "軍事獨裁，以武力維持國家秩序"], "a": 0, "e": "知識分子要求制定明確法律、政府與人民都要遵守，是法治國家。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-97", "no": 97, "c": "c4", "src": "試題寶典評量第 28 頁 第 3 題（原為簡答題）", "st": "講義", "ctx": "在某個國家，最高領袖阿隆總是強調：「我就是法律。」他制定了許多規則，但人民發現，這些規則的執行方式因人而異。例如：一位普通市民因違反宵禁被關進監獄，而政府高官即使做了相同的事，卻毫髮無傷。有人開始質疑這個國家的法律公平性。後來，一群知識分子開始倡導改革，他們要求制定明確的法律，讓政府官員和人民都必須遵守，並建立一個權力分立的制度，以避免權力集中在領袖一人手中。有學者提出，要讓行政、立法、司法三個機關各司其職，互相制衡，確保政府運作公平。", "fig": "", "q": "文中學者建議的制度，最接近哪一種權力分立模式？", "o": ["三權分立", "五權分立", "中央集權", "君主專制"], "a": 0, "e": "讓行政、立法、司法三個機關各司其職、互相制衡，是三權分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-98", "no": 98, "c": "c1", "src": "試題寶典評量第 28 頁 第 4 題（原為簡答題）", "st": "講義", "ctx": "現在多數民主國家為避免同一人掌權過久，違背民主的基本理念，會限制領導人的任期，例如：我國規定總統最多只能連選連任一屆，而有些國家則規定總統不可連任，例如：南韓、菲律賓等；相對的，有些國家的領導人取得政權後，會試圖修法，希望延長任期，擴張自己的權力，例如：中國、俄羅斯等。", "fig": "", "q": "根據文中內容判斷，我國的治理方式是屬於人治還是法治？", "o": ["人治", "法治", "神治", "自治"], "a": 1, "e": "我國限制總統任期、依法治理，屬於法治。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-99", "no": 99, "c": "c6", "src": "試題寶典評量第 28 頁 第 5 題", "st": "講義", "ctx": "現在多數民主國家為避免同一人掌權過久，違背民主的基本理念，會限制領導人的任期，例如：我國規定總統最多只能連選連任一屆，而有些國家則規定總統不可連任，例如：南韓、菲律賓等；相對的，有些國家的領導人取得政權後，會試圖修法，希望延長任期，擴張自己的權力，例如：中國、俄羅斯等。", "fig": "", "q": "文中提到某國領導人試圖修法，此舉最可能會導致下列哪一問題？", "o": ["侵害人民的權利", "限制政府的權力", "造成國會的專制", "政府效率的提升"], "a": 0, "e": "領導人修法延長任期、擴張權力，可能侵害人民的權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-100", "no": 100, "c": "c3", "src": "試題寶典第 38 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "美國歷史上曾有總統意圖使法官離職，但遭嚴正駁回，因為總統沒有權力介入司法；當總統與國會意見相反時，總統必須尊重國會，不能干預。上述內容顯示出美國憲政體制上的設計是採取何項原則？", "o": ["均權制度", "責任政治", "權力分立", "主權在民"], "a": 2, "e": "總統不能介入司法、必須尊重國會，顯示美國採權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-101", "no": 101, "c": "c4", "src": "試題寶典第 38 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "由法國思想家孟德斯鳩提出三權分立的學說是指哪三權？", "o": ["行政權、立法權、監察權", "司法權、考試權、監察權", "立法權、司法權、考試權", "行政權、立法權、司法權"], "a": 3, "e": "三權分立是行政權、立法權、司法權。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-102", "no": 102, "c": "c1", "src": "試題寶典第 39 頁 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "「我們選擇了這樣的社會，選擇了安穩秩序優先，就表示選擇了相互忍讓與磨合的社會。除非對方當下造成你的具體侵害，且有即時排除的迫切需求，否則我們早已把制裁權讓渡給第三方的公權力，該依照固定的法律標準執行。如果人們不信任法律，認為法律保障不了自己就號召私刑，這種作為無疑如西方俗諺所言：在倒掉骯髒的洗澡水的同時，一件把嬰兒給一起倒掉了。」上文中所提及的「這樣的社會」應該是指下列何者？", "o": ["人治社會", "專制社會", "法治社會", "獨裁社會"], "a": 2, "e": "把制裁權交給公權力、依固定法律標準執行，是法治社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-103", "no": 103, "c": "c3", "src": "試題寶典第 39 頁 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "表(一)是維琪所抄寫的筆記，從筆記的內容可以知道老師正在講解哪一個主題？\n表(一)：\n代表國家：五權分立為「中華民國」，三權分立為「美國」\n考試權與監察權獨立與否：五權分立為「考試權獨立於行政權之外，監察權獨立於立法權之外」，三權分立為「行政權兼考試權，立法權兼監察權」\n政府權力：五權分立為「行政、立法、司法、考試、監察」，三權分立為「行政、立法、司法」", "o": ["權力分立與制衡", "地方政府的組成", "人民與政府關係", "國家主要類型"], "a": 0, "e": "比較五權分立與三權分立，是在講權力分立與制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-104", "no": 104, "c": "c3", "src": "試題寶典第 41 頁 第 22 題", "st": "講義", "ctx": "", "fig": "", "q": "為了防止政府權力過大，一般民主國家都把政府的權力分成行政、立法、司法，並分屬於不同的機關，使其彼此相互牽制。下列何者最符合分權制衡的意義？", "o": ["總統可提名司法院大法官，但須經立法院同意後任命", "政府的組成及其具體職權，皆由《憲法》和法律規定", "為了因應物價上漲，政府成立穩定物價小組加以處理", "為了獲得執政權，國內兩大政黨推出候選人進行角逐"], "a": 0, "e": "總統提名大法官須經立法院同意，是權力相互制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-105", "no": 105, "c": "c1", "src": "114上翰林社會2上A卷 第4卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "在以下哪一種類型的國家中，法律的主要目的是鞏固統治者的權力，作為限制人民的工具？", "o": ["法治", "民主", "人治", "權力分立"], "a": 2, "e": "人治社會中統治者的意思就是法律，法律是限制人民的工具，統治者不受法律約束。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-106", "no": 106, "c": "c5", "src": "114上翰林社會2上A卷 第4卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "西方的三權分立原則中，並未將監察權從立法權中獨立出來，此模式可能會引發下列哪一項問題？", "o": ["行政效率不佳", "國會權力過大", "濫用私人或親信", "政黨利益被犧牲"], "a": 1, "e": "三權分立中監察權在立法權之內，可能使國會權力過大。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-107", "no": 107, "c": "c2", "src": "114上翰林社會2上A卷 第4卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據圖(一)內容判斷，警察與人民各自主張行使何者？", "o": ["警察行使權力，駕駛人行使權利", "警察行使權力，駕駛人行使權力", "警察行使權利，駕駛人行使權利", "警察行使權利，駕駛人行使權力"], "a": 0, "e": "警察要求出示證件、搜索是行使權力；駕駛人拒絕無搜索票的搜索是行使權利。", "rep": true, "img": "c3-q107", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-108", "no": 108, "c": "c1", "src": "114上翰林社會2上A卷 第4卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "黃小弟展覽中的中國古代小說，其中的君王口頭禪如下列，哪一句較無法凸顯人治社會的概念？", "o": ["順我者生，逆我者亡", "王子犯法與庶民同罪", "寧可錯殺一百，不可放過一人", "「律法乃朕所定，朕之言便是天律。」"], "a": 1, "e": "「王子犯法與庶民同罪」表示人人受法律約束，是法治的概念。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-109", "no": 109, "c": "c4", "src": "114上翰林社會2上A卷 第4卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "有關三權分立的學說，下列何者敘述正確？", "o": ["司法權由執政政黨運作", "立法機關可掌管行政權", "權力間相互制衡的制度", "監察權自立法權中獨立"], "a": 2, "e": "三權分立是權力間相互制衡的制度。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-110", "no": 110, "c": "c6", "src": "114上翰林社會2上A卷 第4卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "現代民主國家為了防止政府濫權，而建構出權力受限的「有限政府」。此政府的運作原則是透過將國家權力與運作方式納入下列何者之中？", "o": ["《憲法》的規範", "統治者的良知", "國際競爭力", "文化環境改善"], "a": 0, "e": "有限政府將國家權力與運作方式納入《憲法》規範。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-111", "no": 111, "c": "c4", "src": "114上翰林社會2上A卷 第4卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "在三權分立的國家中，哪一個權力必須超出黨派，依據法律來獨立行使職權？", "o": ["行政權", "立法權", "司法權", "考試權"], "a": 2, "e": "司法權必須超出黨派，依法獨立行使。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-112", "no": 112, "c": "c2", "src": "114上翰林社會2上A卷 第4卷 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "父母不履行使該就學的學齡兒童接受國民教育的義務，國家可依法處罰，並強迫入學。上述現象主要說明下列何者的意義？", "o": ["政府行使的權力", "人民行使的權力", "政府行使的權利", "人民行使的權利"], "a": 0, "e": "國家依法處罰不讓孩子就學的父母，是政府行使權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-113", "no": 113, "c": "c4", "src": "114上翰林社會2上A卷 第4卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "普遍被現代民主國家所接受的三權分立的學說，是由法國思想家孟德斯鳩提出。下列何者是他當初提出該學說的主要目的？", "o": ["防止權力濫用", "侵犯人民權利", "確立專制發展", "維護政府權威"], "a": 0, "e": "孟德斯鳩提出三權分立的目的是防止權力濫用。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-114", "no": 114, "c": "c5", "src": "114上翰林社會2上A卷 第4卷 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "孫中山先生考察西方三權分立制度後，提出許多不同的見解，下列何者不是他所提出的見解？", "o": ["監察權從立法權中獨立", "考試權從行政權中獨立", "修改三權分立並提出五權分立", "五權分立為我國地方政府體制"], "a": 3, "e": "五權分立是我國中央政府體制，不是地方政府體制。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-115", "no": 115, "c": "c1", "src": "114上翰林社會2上A卷 第4卷 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列是某次社會課程探討議題的重點。根據內容判斷，該項議題應為下列何者的特色？\n重點內容：＊政府依法行政、＊國家內所有人都必須遵守法律", "o": ["人治國家", "法治國家", "獨裁國家", "君主國家"], "a": 1, "e": "政府依法行政、人人都守法，是法治國家的特色。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-116", "no": 116, "c": "c3", "src": "114上翰林社會2上A卷 第4卷 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "政治學上有句名言：「權力使人腐化，絕對的權力，絕對的腐化。」意旨權力不能集中在同一群人手中，以免權力被濫用，因而現代國家對於中央政府體制的設計依此理論採用何種原則？", "o": ["中央集權", "權力分立", "人治社會", "主權在民"], "a": 1, "e": "權力不能集中，所以政府體制採權力分立。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-117", "no": 117, "c": "c6", "src": "114上翰林社會2上A卷 第4卷 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "佩芳利用周末假期整理有關「有限政府」主題的公民報告，她檢索查詢到的資料，仔細分析，並在製作簡報時特別摘要其特點，關於上述報告主題，下列何者應該放入佩芳簡報內容中？", "o": ["政府權力應集中於中央", "政府權力受政客規範", "政府權力受到限制", "政府權力無限擴大"], "a": 2, "e": "有限政府的特點是政府權力受到限制。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-118", "no": 118, "c": "c3", "src": "114上翰林社會2上A卷 第4卷 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "現代國家對於中央政府體制的設計，大多將各種功能的權力加以分散，交由不同的政府機關執行。這樣設計是為了達到下列何種目的？", "o": ["權力集中", "分權制衡", "人治社會", "主權在民"], "a": 1, "e": "權力分散交由不同機關，是為了分權制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-119", "no": 119, "c": "c3", "src": "114上翰林社會2上A卷 第4卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據下表的內容判斷，下列相關說明何者正確？\n表格：憲法增修條文第二條第三項\n甲、發布時機：為避免國家或人民遭遇緊急危難或應付財政經濟上重大變故\n乙、發布機關：總統\n丙、變更／廢止：須於發布命令後十日內提交立法院追認\n丁、效力：如立法院不同意，該緊急命令立即失效", "o": ["甲——限制發布的條件，來約束人民的權利", "乙——作為統治者，權力不會受到法律約束", "丙——需要有制衡機制，避免淪為人治社會", "丁——可以看出我國監察權大於總統的行政權"], "a": 2, "e": "緊急命令須經立法院追認，需要制衡機制，避免淪為人治。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-120", "no": 120, "c": "c1", "src": "114上翰林社會2上A卷 第4卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "希臘哲學家亞里斯多德曾說：「法治比任何一個人的統治來得更好」，這句彰顯出法治社會中法律的哪一項主要功能？", "o": ["擴大君主權力", "限制人民行為", "防止個人濫權", "強化統治權力"], "a": 2, "e": "法治比個人統治好，因為法律可防止個人濫權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-121", "no": 121, "c": "c4", "src": "114上翰林社會2上A卷 第4卷 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "關於孟德斯鳩的三權分立學說，哪一項觀念正確？", "o": ["由行政機關監督政府官員", "由立法機關審查政府預算", "由司法機關獨立制定法律", "由考試機關為國公正舉才"], "a": 1, "e": "三權分立中，立法機關負責制定法律、審查政府預算。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-122", "no": 122, "c": "c6", "src": "114上翰林社會2上A卷 第4卷 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "大聯國將調整總統職權如下列所示，這個國家政府未來的發展狀況，最可能呈現為何？\n★總統任期 10 年，無連任次數限制。\n★由總統直接任命行政、立法、司法首長。\n★總統可否決立法院修訂的法律。\n★取消避免民意過度膨脹的制度。", "o": ["形成有限政府，依法行政", "三權分立並能相互牽制", "立法權過大導致專制獨裁", "總統權力過大且缺乏制衡"], "a": 3, "e": "總統任期長、兼任各院院長、可否決法律、取消罷免彈劾，權力過大且缺乏制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-123", "no": 123, "c": "c3", "src": "114上翰林社會2上A卷 第4卷 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "公民監督國會聯盟召開記者會，指出立法院 115 年度提出的國會外交預算高達六千萬元，要求立委應公開出國費用項目、行程目的及成效供民眾檢視。上述要求是因為目前的制度，立法院自己編列的預算自己審，且內部稽核制度不透明，可能導致下列何種問題？", "o": ["缺乏人力", "缺乏效率", "缺乏制衡", "缺乏執行力"], "a": 2, "e": "立法院自己編預算自己審，缺乏制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-124", "no": 124, "c": "c4", "src": "114上翰林社會2上A卷 第4卷 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)是疫情相關的消息，依圖判斷，立法院可提出法律修正案，是因為擁有下列何種權力？\n圖(二)內容：「嚴重特殊傳染性肺炎（COVID-19）疫情嚴峻，(甲)三讀通過《嚴重特殊傳染性肺炎防治及紓困振興特別條例部分條文修正案》。」", "o": ["司法權", "考試權", "行政權", "立法權"], "a": 3, "e": "提出法律修正案是立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-125", "no": 125, "c": "c1", "src": "114上翰林社會2上A卷 第4卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國罹患新冠肺炎疫情嚴重期間，曾發生政府為避免疫情擴散而禁止人民出國一事，引發外界質疑此舉是否欠缺法律明確授權而有違憲疑慮，政府因而多次對外公開說明政策相關依據。上述疑慮，是因政府政策有可能違反下列何者？", "o": ["人治社會", "多數民意", "依法行政", "總統指令"], "a": 2, "e": "政府限制人民權利須有法律明確授權，否則違反依法行政。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-126", "no": 126, "c": "c5", "src": "114上翰林社會2上A卷 第4卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列是一則國內新聞報導的節錄內容，依內容判斷，監察院的權力產生是基於何種原則？「監察院是我國獨特的中央政府體制，類似古代『搦矯諷刺』制度，監察院接受人民陳情，調查官員是否有行政疏失，再據以糾正、糾舉或彈劾。」", "o": ["政黨輪替", "權力分立", "主權在民", "無限政府"], "a": 1, "e": "監察院獨立行使監察權，是基於權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-127", "no": 127, "c": "c5", "src": "114上翰林社會2上A卷 第4卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)是我國某中央政府機關在網頁上發布的消息，依圖判斷，此為屬於何種政府權力的執行？\n圖(三)內容：「111 年公務人員特種考試司法人員考試、與 111 年專門職業及技術人員高等考試建築師考試，定在 111 年 8 月 6 日舉行第一試。」", "o": ["考試權", "立法權", "行政權", "監察權"], "a": 0, "e": "舉辦國家考試是考試權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-128", "no": 128, "c": "c4", "src": "114上翰林社會2上A卷 第4卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列是政府發布的一則訊息。這是何項政府權力具體發揮的結果？「因應農曆春節即將到來，院長請警政署加強維護守望、宣導通報、查訪防竊並嚴辦非法聚賭等四大工作。」", "o": ["行政權", "考試權", "立法權", "司法權"], "a": 0, "e": "行政院院長指示警政署加強治安工作，是行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-129", "no": 129, "c": "c6", "src": "114上翰林社會2上A卷 第4卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列哪一個歷史事件較符合有限政府的精神？", "o": ["袁世凱強迫國會選他擔任總統，之後又解散國會，立法允許總統終身連任並指定繼承人", "凱撒削弱了元老院議事權，將行政、軍事和宗教權力集中於自己手中，控制財政、司法和軍隊", "史達林成立祕密警察監控社會，負責逮捕、審判和處決任何被懷疑對政權不忠的人", "康熙皇帝強調以法治國，要求官員依法審判，不受情感或政治考量影響"], "a": 3, "e": "康熙要求官員依法審判，最接近限制權力、依法治理的精神；其他是專權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-130", "no": 130, "c": "c6", "src": "114上翰林社會2上A卷 第4卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "2025 年元月我國總統召見五院院長進行國政會商，特地準備「花開富貴五福臨門」紅白雙杯五入禮盒，送給五院院長。下列對禮物意涵的推測，何者最符合我國的中央政府體制？", "o": ["五院歸總統管轄，須聽命於總統", "五院需互相合作，不可互相監督", "五院須互相制衡，建構有限政府", "五院須保持對立，堅持黨派利益"], "a": 2, "e": "五院互相制衡，建構有限政府。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-131", "no": 131, "c": "c3", "src": "114上翰林社會2上A卷 第4卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列是知名的英國政治哲學家洛克說過的一段話，根據內容判斷，這段話最可能是在傳遞下列何種觀念的重要？「如果執政者失去了約束，在同一人手裡既有立法權又有執法權，就難免使他們不遵守自己所定的法律。」", "o": ["權力分立", "主權在民", "人治", "法治"], "a": 0, "e": "洛克說立法權與執法權不應集中在同一人手裡，是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-132", "no": 132, "c": "c6", "src": "114上翰林社會2上A卷 第6卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "當政府的作為有違反《憲法》規範的疑慮時，必須透過司法機關審理法律是否違憲，以確保政府權力運作符合《憲法》要求，上述審理法律的單位為何？", "o": ["行政院", "憲法法庭", "立法院", "審計長"], "a": 1, "e": "審理法律是否違憲的是憲法法庭。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-133", "no": 133, "c": "c3", "src": "114上翰林社會2上A卷 第6卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(一)中是我國與法律相關的權力，交由不同的機關執行，這不能用來解釋下列哪一個概念？\n圖(一)：金字塔頂端(甲)「法律的執行：依法行政」、左下(丙)「法律的裁決：依據法律獨立審判，以保障人民權益」、右下(乙)「法律的制定：遵循憲法規範，經民主程序制定法律」", "o": ["法治社會", "三權分立", "權力擴張", "有限政府"], "a": 2, "e": "法律的執行、制定、裁決交給不同機關，符合法治、權力分立、有限政府，不能解釋權力擴張。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-134", "no": 134, "c": "c2", "src": "114上翰林社會2上A卷 第6卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "某校國學生因持塑膠球棒打人，被害人於隔天報案，要求該生提出傷害告訴，警方接獲報案，直接進學校將學生帶回派出所。但因隔日截獲已不符合現行犯可直接進行逮捕的法律規定，警方需先申請得票，或是通知監護人帶學生到派出所，此案執法過程有瑕疵，主管機關將要求申誡處分。從權利與權力的角度分析此案，下列敘述何者正確？", "o": ["文中老師有提起訴訟的權力", "學生有不被任意逮捕的權力", "現行犯有拒絕被逮捕的權力", "主管機關有懲戒警員的權力"], "a": 3, "e": "主管機關可依法懲戒警員，是行使權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-135", "no": 135, "c": "c3", "src": "114上翰林社會2上A卷 第6卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "權力分立是現代民主國家發展的重要基石。關於權力分立的目的之敘述，下列何者錯誤？", "o": ["避免專權政治", "保持權力平衡", "限制人民權利", "追求政府效率"], "a": 2, "e": "權力分立是為了保障人民權利，不是限制人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-136", "no": 136, "c": "c3", "src": "114上翰林社會2上A卷 第6卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列名言在警惕民主國家的運作要注意哪一原則？「權力使人腐化，絕對的權力，絕對的腐化。——19 世紀英國歷史學家阿克頓爵士」", "o": ["必須去保保障權力", "所有權力皆應捨棄", "將權力還與人民共享", "權力分立相互制衡"], "a": 3, "e": "艾克頓的名言提醒要權力分立、相互制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-137", "no": 137, "c": "c1", "src": "114上翰林社會2上A卷 第6卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "存在於法治社會中的「法律」，其功能為下列何者？", "o": ["保障人民權利", "強化君主權力", "限制人民工具", "擴張政府職權"], "a": 0, "e": "法治社會中法律的主要功能是保障人民的權利，並限制政府的權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-138", "no": 138, "c": "c4", "src": "114上翰林社會2上A卷 第6卷 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "美國政府體制的設計參考孟德斯鳩學說，而具備下列哪一特色？", "o": ["採行行政、立法、監察三權分立", "總統掌握立法權，負責執行政策", "法院掌握司法權，獨立行使職權", "國會掌握行政權，審查政府預算"], "a": 2, "e": "美國參考孟德斯鳩學說，由法院掌握司法權、獨立行使職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-139", "no": 139, "c": "c3", "src": "114上翰林社會2上A卷 第6卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)是芳芳在課堂報告時引用的資料，她報告的主題最可能是下列何者？\n圖(三)：\n三權分立：行政權、立法權、司法權\n五權分立：行政權、立法權、司法權、考試權、監察權", "o": ["主權在民", "無限政府", "權力分立", "法治社會"], "a": 2, "e": "比較三權與五權分立，主題是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-140", "no": 140, "c": "c6", "src": "114上翰林社會2上A卷 第6卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列是幾位重量級人物的對話，何者言論較符合有限政府特色，施政必須向人民負責？", "o": ["國王：我要將權力交給子孫，讓他們繼續掌權", "總理：我國女王沒有實權，我透過選舉取得行政權", "主席：我國是黨、政、軍合一的國家，執政非常有效率", "總裁：沒人敢跟我競選，不用擔心輪替的問題"], "a": 1, "e": "總理經選舉取得行政權、向人民負責，符合有限政府。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-141", "no": 141, "c": "c1", "src": "114上翰林社會2上B卷 第4卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "新聞報導：「為遏止酒駕，行政院法務部建議修法，只要再犯酒後駕車，警方可依法聲請法院裁定拘留 1 日以上、3 日以下，以多重嚇阻酒駕行為。」上述政府修法的主要功能為何？", "o": ["限制政府施政", "增加政府收入", "約束人民行為", "保障人民權利"], "a": 2, "e": "修法提高酒駕處罰，主要功能是約束人民行為（依原卷答案改為 C）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-142", "no": 142, "c": "c4", "src": "114上翰林社會2上B卷 第4卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "美國是最早實施三權分立的國家，為了保障人民的權利和限制政府的權力，將孟德斯鳩三權分立的理論落實於《美國憲法》中。其三權分立所代表的機構其中之一，為負責執行政策的內閣。上述所指的內閣是掌握該理論中的哪一權力？", "o": ["監察權", "司法權", "立法權", "行政權"], "a": 3, "e": "負責執行政策的內閣掌握行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-143", "no": 143, "c": "c2", "src": "114上翰林社會2上B卷 第4卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "「權利」是指人民依法享有的各種利益，且不受國家非法侵犯。下列何者是「權利」的展現？", "o": ["大學生遊行抗議高學費", "警察臨檢取締非法幫派", "騎乘機車佩戴安全帽", "政府依法拆除頂樓違建"], "a": 0, "e": "大學生遊行抗議是行使人民的權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-144", "no": 144, "c": "c3", "src": "114上翰林社會2上B卷 第4卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "老師要求全班分組，並針對各國政治制度發表意見，圖(一)為其中一組的主題大綱。從內容判斷，此組應是以何者為研究主題？", "o": ["主權在民", "三權分立", "五權分立", "國家主權"], "a": 2, "e": "孫中山的理論、中國考試與監察制度、參考西方分權思想，主題是五權分立（依原卷答案改為 C）。", "rep": false, "img": "c3-q144", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-145", "no": 145, "c": "c2", "src": "114上翰林社會2上B卷 第4卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列何者是指在法律的保障之下，人民有避免受到侵害且享有追求某種利益的權益？", "o": ["權力", "權利", "權能", "權限"], "a": 1, "e": "受法律保障、避免受侵害、追求利益的權益是權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-146", "no": 146, "c": "c2", "src": "114上翰林社會2上B卷 第4卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列何者是指一種上下支配的力量，擁有某種優勢的資源而有能力去執行某些事務，且具有一定的強制性？", "o": ["權利", "權力", "義務", "責任"], "a": 1, "e": "上下支配、具強制性的力量是權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-147", "no": 147, "c": "c3", "src": "114上翰林社會2上B卷 第4卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列哪一概念是指國家將各種功能的權力加以分散，並交由不同的政府機關執行，以免權力被濫用？", "o": ["主權在民", "人治社會", "權力分立", "法治政治"], "a": 2, "e": "權力分立是將國家權力分散交由不同機關行使、彼此制衡，以防止權力濫用、保障人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-148", "no": 148, "c": "c3", "src": "114上翰林社會2上B卷 第4卷 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "英國歷史學家艾克頓爵士曾說：「權力使人腐化，絕對的權力，絕對的腐化。」下列關於此段話的說明何者正確？", "o": ["掌權者不應該擁有權力", "掌權者權力集中弊大於利", "所有的君主都不會造成權力腐化", "五權分立體制優於三權分立體制"], "a": 1, "e": "掌權者權力集中容易腐化，弊大於利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-149", "no": 149, "c": "c1", "src": "114上翰林社會2上B卷 第4卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據圖(二)提及的草案內容判斷，若未來此草案通過，則該法主要應會發揮下列何項功能？\n圖(二)剪報文字：「某政黨提出『納稅者權利保護法』草案，包括落實納稅者生存權保障、負責實質賦稅的公平課稅理念、設置納稅者權利保護官……等，該法獲得朝野支持，希望能早日完成立法。」", "o": ["保障人民權利", "落實責任政治", "鞏固君主體制", "保障統治者權力"], "a": 0, "e": "「納稅者權利保護法」主要在保障人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-150", "no": 150, "c": "c5", "src": "114上翰林社會2上B卷 第4卷 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "由於《住發法》修法至 2020 年已超過 3 年，但是攸關租金補貼與社會住宅租金制定的「可負擔計算基準」，行政院內政部卻未依法在 2 年期限內訂定，使得弱勢租屋族群的補貼機制依舊處在舊制，導致負擔增加，因此「相關單位」的民意代表表示將會持續監督行政機關儘速提出改善方案，以合理照顧更多弱勢的民眾。依上文所述，「相關單位」主要是指擁有五權分立中的何種權力？", "o": ["考試權", "行政權", "立法權", "司法權"], "a": 2, "e": "監督行政機關的「相關單位」是立法委員，屬立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-151", "no": 151, "c": "c2", "src": "114上翰林社會2上B卷 第4卷 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國《憲法》第 7 條明訂只要是中華民國人民，無分男女、宗教、種族、階級、黨派，在法律上一律平等，而此所謂的平等權，並非著重與式的「形式平等」，而是強調人人「實質平等」。上文所述的平等權內涵應是指下列何者？", "o": ["人民的權力", "人民的責任", "人民的義務", "人民的權利"], "a": 3, "e": "平等權是人民的權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-152", "no": 152, "c": "c5", "src": "114上翰林社會2上B卷 第4卷 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)為我國中央政府機關間彼此的權力說明。由圖中內容判斷，其可彰顯出下列何種憲政精神？", "o": ["基本人權", "公民投票", "法治政治", "權力分立"], "a": 3, "e": "各機關彼此監督制衡，彰顯權力分立。", "rep": false, "img": "c3-q152", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-153", "no": 153, "c": "c2", "src": "114上翰林社會2上B卷 第4卷 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "所謂的權力，學者達爾（R. Dahl）指出，乃是指「A 可以使 B 去做 B 原本不想做的事」的能力。下列何者符合上述概念的說明？", "o": ["人民有信仰各種宗教的自由", "人民有納稅、服兵役之義務", "衛福部要求民眾外出須全程佩戴口罩", "警方沒有證據不可偷聽犯罪嫌疑人電話"], "a": 2, "e": "衛福部要求民眾戴口罩，是使人做原本不想做的事，屬權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-154", "no": 154, "c": "c1", "src": "114上翰林社會2上B卷 第4卷 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)為史都國人民對其國家統治者的敘述，由內容判斷，下列有關該國的敘述何者正確？\n圖(四)史都國統治者特徵：1.統治者在法之上 2.統治者既是執法者也是立法者 3.統治者可以朝令夕改法律 4.國家依統治者的意見為依歸 5.國家行政效率佳", "o": ["屬於法治社會", "屬於人治社會", "屬於民主社會", "現況與臺灣相同"], "a": 1, "e": "統治者在法律之上、可朝令夕改，是人治社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-155", "no": 155, "c": "c1", "src": "114上翰林社會2上B卷 第4卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "下表為不同社會形態的特徵說明，下列相關說明何者正確？\n表格：\n甲形態：特徵1「人民是權利的主體」、特徵2「保護人民利益」、特徵3「社會長治久安」\n乙形態：特徵1「少數人是權利主體」、特徵2「保護少數人利益」、特徵3「社會時常動亂」", "o": ["甲是指人治社會", "乙是指法治社會", "甲的代表國家是美國", "乙的法律是由人民選出代表制定"], "a": 2, "e": "甲：人民是權利主體、保護人民利益，是法治社會，代表國家如美國。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-156", "no": 156, "c": "c5", "src": "114上翰林社會2上B卷 第4卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列為某國政府體制下承雇政府權力的說明。該政府權力應是指「五權分立」中的何者？「藉政府主管分職，用人治民之規模、官吏入仕之途徑，考選之方式，分等定律之規常，考課獎懲之實施等。」", "o": ["司法權", "監察權", "立法權", "考試權"], "a": 3, "e": "管理官吏入仕、考選、考課獎懲，是考試權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-157", "no": 157, "c": "c4", "src": "114上翰林社會2上B卷 第4卷 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(五)為政府權力分立的示意圖，這是目前世界上大多數國家採用的政治制度，由圖中內容判斷，甲、乙、丙依序應為下列何者？", "o": ["行政權、立法權、司法權", "立法權、司法權、行政權", "行政權、司法權、立法權", "司法權、行政權、立法權"], "a": 2, "e": "甲負責法律的執行（行政權）、乙法律的裁決（司法權）、丙法律的制定（立法權）。", "rep": true, "img": "c3-q157", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-158", "no": 158, "c": "c3", "src": "114上翰林社會2上B卷 第4卷 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "起草《憲法》的美國總統麥迪遜有一句名言：「如果人是天使，將無需政府；如果天使統治人，將無需對政府進行任何限制。」這樣的理念奠定了美國的憲政體制，達到下列哪一目的？", "o": ["權力集中以收強人政治之效", "政府權力應相互制衡與平衡", "不對政府限制美國才能強大", "擴張人民權利縮小政府規模"], "a": 1, "e": "人不是天使，所以要限制政府，讓權力相互制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-159", "no": 159, "c": "c6", "src": "114上翰林社會2上B卷 第4卷 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "民主國家中主要是藉由何者來保障人民的基本權利以及規範政府的權力？", "o": ["憲法", "國會", "司法機關", "國家統治者"], "a": 0, "e": "民主國家以《憲法》保障人民權利、規範政府權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-160", "no": 160, "c": "c5", "src": "114上翰林社會2上B卷 第4卷 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "明清時代的科舉制度是古代中國最重要的選才制度，自隋唐時期開始，以經典書籍測驗來取代血緣、身分選才，共分為鄉試、會試、殿試三層。此與我國現今何種政府權力最相近？", "o": ["監察權", "考試權", "行政權", "立法權"], "a": 1, "e": "科舉是選拔人才，相當於考試權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-161", "no": 161, "c": "c5", "src": "114上翰林社會2上B卷 第4卷 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "唐太宗非常欣賞魏徵的直言坦蕩，因此任命他為諫議大夫，經常向他詢問政事得失，而魏徵也經常直諫太宗及監督文武百官，讓他成為中國歷史上最著名的諫臣之一。若以我國憲政體制來看，魏徵所擔任的職務應是行使下列何種權力？", "o": ["司法權", "行政權", "監察權", "考試權"], "a": 2, "e": "魏徵直諫、監督百官，相當於監察權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-162", "no": 162, "c": "c1", "src": "114上翰林社會2上B卷 第4卷 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "所謂「法治」就是依法而治，也就是以法律作為治理國家的依據。下列何者不符合此一原則？", "o": ["國家擁有法律即屬於法治國家", "由人民選出的代表來制定國家法律", "政府只是法律執行者，必須依法行政", "法治國家中人民與政府皆須受法律約束"], "a": 0, "e": "有法律不等於法治；法治是政府與人民都受法律約束。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-163", "no": 163, "c": "c2", "src": "114上翰林社會2上B卷 第4卷 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "孫中山先生創立的五權憲法，是基於三民主義理論所制定，後來成為《中華民國憲法》的重要參考，他將西方學說的行政權分出考試權、立法權分出監察權，而形成「五權分立」。上文的「權」其意義應為下列何者？", "o": ["權力", "權利", "權宜", "權證"], "a": 0, "e": "五權分立的「權」是權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-164", "no": 164, "c": "c6", "src": "114上翰林社會2上B卷 第4卷 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "「○○○○」是指在權力、職能和規模上都受到《憲法》和法律的嚴格約束及限制，它界定了政府權力的界線，從而有效地防止政府對公眾自由和利益的肆意踐踏，維護公民的合法權益。上述的「○○○○」是指下列何者？", "o": ["有限政府", "萬能政府", "無限政府", "人治社會"], "a": 0, "e": "權力受《憲法》和法律限制的政府，是有限政府。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-165", "no": 165, "c": "c4", "src": "114上翰林社會2上B卷 第4卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據上述，美國總統擁有何種政府權力？", "o": ["司法權", "立法權", "監察權", "行政權"], "a": 3, "e": "美國總統擁有行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-166", "no": 166, "c": "c4", "src": "114上翰林社會2上B卷 第4卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據美國政權制衡來看，上述的「國會」主要具備下列哪一特色？", "o": ["負責執行政策治理國家", "制定法律與監督行政機關", "超出黨派獨立行使司法權", "公正的選拔人才避免弊端"], "a": 1, "e": "國會制定法律並監督行政機關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-167", "no": 167, "c": "c3", "src": "114上翰林社會2上B卷 第4卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據上述，下列相關說明何者正確？", "o": ["總統簽署的命令位階高於《美國憲法》", "總統簽署命令讓人民權利獲得充分保障", "聯邦法院擁有司法權可以制衡美國總統", "總統可簽署行政命令表示美國屬於人治社會"], "a": 2, "e": "聯邦法院以司法權制衡總統的行政命令。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-168", "no": 168, "c": "c4", "src": "114上翰林社會2上B卷 第4卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "上文中提到「西方的制度」，是指何種制度？", "o": ["君主專制", "獨裁政府", "三權分立", "五權分立"], "a": 2, "e": "西方的制度是三權分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-169", "no": 169, "c": "c5", "src": "114上翰林社會2上B卷 第4卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "孫中山先生最後提出的政治制度為下列何者？", "o": ["三權分立", "五權分立", "君主專制", "獨裁政府"], "a": 1, "e": "孫中山提出五權分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-170", "no": 170, "c": "c5", "src": "114上翰林社會2上B卷 第4卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "孫中山先生將哪一種權力獨立出來，可以避免行政機關濫用私人的弊端？", "o": ["考試權", "立法權", "司法權", "監察權"], "a": 0, "e": "考試權獨立可避免行政機關濫用私人。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-171", "no": 171, "c": "c5", "src": "114上翰林社會2上B卷 第4卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國採用孫中山先生的理論，為了避免議會權力過大的缺陷，將哪一種權力由立法權獨立出來？", "o": ["司法權", "考試權", "監察權", "行政權"], "a": 2, "e": "為避免議會權力過大，將監察權由立法權獨立出來。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-172", "no": 172, "c": "c3", "src": "114上翰林社會2上B卷 第6卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據下列內容判斷，此為何種政治學概念？「是現代國家統治模式的一種，其設計理念是將各種國家公權力分散，不使其集中在單一機關內，是當前世界上多數國家採用的一種政治制度。」", "o": ["人治社會", "主權在民", "權力分立", "責任政治"], "a": 2, "e": "將公權力分散、不集中於單一機關，是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-173", "no": 173, "c": "c4", "src": "114上翰林社會2上B卷 第6卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "2020 年英國脫歐後，當時的英國首相強森為安撫朝野民心，對政府內閣進行大幅調整（如圖(一)）。根據其內閣改組的陣容來看，強森與內閣主要是掌握政府的何種權力？\n圖(一)：財政大臣、內政大臣、外交大臣、國防大臣、環境大臣、衛生大臣。", "o": ["司法權", "立法權", "監察權", "行政權"], "a": 3, "e": "首相與內閣掌握行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-174", "no": 174, "c": "c2", "src": "114上翰林社會2上B卷 第6卷 第 7 題", "st": "考卷", "ctx": "", "fig": "畫底線處：(甲)警方對民眾實施臨檢；(乙)民眾可提告；(丙)民眾為了維護自己的利益可進行錄影；(丁)員警可依「妨害公務」等理由當場逮捕民眾", "q": "近年警民衝突事件中，頗具爭議的莫過於警方對民眾實施臨檢，合法臨檢的前提為員警須出示證件以證明身分，且得在公共場所進行，若在警方強制執行搜尋時起爭執，民眾可提告。臨檢過程中四位民眾為了維護自己的利益可進行錄影，但民眾不可以辱罵員警，否則員警可以「妨害公務」等理由當場逮捕民眾。上文中畫底線部分何者屬於政府的「權力」？", "o": ["(甲)、(乙)", "(乙)、(丙)", "(甲)、(丁)", "(丙)、(丁)"], "a": 2, "e": "甲（警方臨檢）、丁（員警依法逮捕）是政府的權力；乙（提告）、丙（錄影）是人民的權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-175", "no": 175, "c": "c1", "src": "114上翰林社會2上B卷 第6卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "《漢書·張釋之傳》記載漢文帝時代，廷尉張釋之因縣人驚動漢文帝乘輿的事件，展現出不畏皇權依法審理的態度，最後獲得皇帝認同，並收回懲處。下列關於上述文章的時代背景，何者敘述正確？", "o": ["屬於人治社會", "人民選出代表制定法律", "政府不可任意侵害人民權利", "人民與統治者皆須受到法律制裁"], "a": 0, "e": "漢文帝時代皇權至上，屬人治社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-176", "no": 176, "c": "c3", "src": "114上翰林社會2上B卷 第6卷 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)為美國立法權與司法權彼此間的權力關係示意圖。圖中主要說明政府體制中的何種概念？\n圖(三)：國會與最高法院之間，標示「可以宣告法律不符合憲法」、「任免同意最高法院大法官」", "o": ["五權分立", "主權在民", "責任政治", "分權制衡"], "a": 3, "e": "國會與法院彼此制約，是分權制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-177", "no": 177, "c": "c1", "src": "114上翰林社會2上B卷 第6卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "法治社會是與人治社會相對的概念，兩者是用來說明一個社會上的公共事務如何運作的模式。下列關於兩者的說明，何者正確？", "o": ["人治社會無法律，法治社會有法律", "現代民主國家基本上是屬於人治社會", "人治社會的法律主要是用來限制人民的工具", "法治社會中法律會隨著統治者的需求而推定"], "a": 2, "e": "人治社會的法律主要是限制人民的工具。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-178", "no": 178, "c": "c1", "src": "114上翰林社會2上B卷 第6卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "近日安德國某地區新建工廠完工，地方政府舉辦慶祝活動，餐敘期間因部分人員行為不當，而引起批評。事件曝光後，該國最高領導人震怒，隨即未遵照法律與知會相關單位，便下令嚴懲所有相關人員，甚至閉門審會場所，其他地區的類似場所也被迫停業，引發民眾恐慌與不安。關於安德國的敘述，何者正確？", "o": ["沒有法律存在", "屬於法治社會", "最高領導人的意思即是法律", "法律主要目的為限制政府權力"], "a": 2, "e": "最高領導人一下令就嚴懲、停業，領導人的意思就是法律，是人治。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-179", "no": 179, "c": "c2", "src": "114上翰林社會2上B卷 第6卷 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "日前一名取得居留的巴勒斯坦學生，在學校發起抗議，以色列表對加薩地區發動戰爭，而遭到移民局逮捕，美國政府認為他宣揚恐怖主義而依法將其拘捕並驅逐出境。對此人權團體認為政府行徑不妥且帶有歧視意味，會對校園內的學習環境帶來分化的負面影響，並表示關閉政府作法應避免損害社會對法治的信任。根據上文，下列哪一說明最為正確？", "o": ["美國可能是屬於人治社會", "將人驅逐出境為政府權力", "接受教育是屬於人民權力", "發起抗議為平等權的保障"], "a": 1, "e": "政府依法拘捕、驅逐出境是行使權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-180", "no": 180, "c": "c5", "src": "114上翰林社會2上C卷 第4卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "部分國家的行政體制，執政者在遴選行政團隊時，都有產生疑似「用人不當」的疑慮，依我國現行體制中，何者是孫中山為了防止行政機關「用人不當」弊病，特將該權力獨立出來？", "o": ["司法權", "考試權", "監察權", "立法權"], "a": 1, "e": "為防止行政機關用人不當，將考試權獨立出來。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-181", "no": 181, "c": "c1", "src": "114上翰林社會2上C卷 第4卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "電視連續劇清宮劇後宮女人心中，爭權的皇后看到哪位嬪妃不順己意，便可以直接審訊並依法加以刑罰。關於上述體制，何者說明正確？", "o": ["清朝屬於法治的社會", "皇后的權力受法律約束", "法律是限制人民的工具", "法律可保障人民的權利"], "a": 2, "e": "皇后可任意審訊刑罰，法律是限制人民的工具。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-182", "no": 182, "c": "c4", "src": "114上翰林社會2上C卷 第4卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列是上課時，討論有關三權分立的制度，同學針對其角色扮演表述的臺詞，何人的說法完全正確？", "o": ["小呂：「我掌管司法權，審理訴訟案件是我的主要工作。」", "小治：「我掌管司法權，代表公民行使制定法律的工作。」", "小中：「我掌管行政權，代表人民修改監督政府的權力。」", "小均：「我掌管立法權，超然獨立，監督行政和司法權。」"], "a": 0, "e": "小呂說司法權負責審理訴訟，完全正確。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-183", "no": 183, "c": "c1", "src": "114上翰林社會2上C卷 第4卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "小治在準備關於「法治社會所代表的意義」之講座資料，他最可能提出下列哪一項論述？", "o": ["現今的社會，多數國家仍是以人治為主", "社會上仍仰賴宗教、習俗等非正式規範", "法律明確規定人民與政府應遵守的事項", "統治者可以任意訂定人民的權利及義務"], "a": 2, "e": "法治社會以法律明確規定人民與政府應遵守的事項。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-184", "no": 184, "c": "c3", "src": "114上翰林社會2上C卷 第4卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "第四任美國總統麥迪遜說：「如果人是天使，將無需政府；如果天使統治人，將無需對政府做任何限制。」有關這段話的意涵，下列何者說明正確？", "o": ["因為人都是天使，現在所有國家都沒有政府", "因為天使統治人，現在政府權力都沒有限制", "因為人都不是天使，所以需要力量相互約束", "因為人都不是天使，所以放棄上天堂的念頭"], "a": 2, "e": "因為人都不是天使，所以需要政府，且政府權力也須受限制。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-185", "no": 185, "c": "c4", "src": "114上翰林社會2上C卷 第4卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "在英國，為了讓政府施政能接受民眾監督，同時避免民意機關凌駕行政，形成兩種權力相互制衡的局面。然而，在這樣的制度下，難免會出現政黨立場或利益衝突的情形。為此，另設有一個獨立超然的第三種權力，用以監督兩者是否妥當。這項權力是指哪一項？", "o": ["司法權", "考試權", "監察權", "立法權"], "a": 0, "e": "獨立超然、監督行政與立法的第三種權力是司法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-186", "no": 186, "c": "c1", "src": "114上翰林社會2上C卷 第4卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "現代民主國家，即使警察也不能擅自進入民宅搜索罪犯，相關偵辦皆須經過法定程序辦理，才能搜索相關證據及嫌疑犯。由此可見，法律能發揮何種作用？", "o": ["保障人民權利", "約束人民行為", "伸張政府權力", "發揚人治精神"], "a": 0, "e": "警察須依法定程序搜索，法律保障人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-187", "no": 187, "c": "c2", "src": "114上翰林社會2上C卷 第4卷 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "權力是指個人或團體掌握某種優勢資源，以強制的力量影響他人行為，並有能力執行某些事務。下列何者為「權力」的展現？", "o": ["民眾申請遊行的路線", "出版社將創作集結成冊", "政府將違規者吊銷駕照", "災民請求國家提供救助"], "a": 2, "e": "政府吊銷違規者駕照是行使權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-188", "no": 188, "c": "c3", "src": "114上翰林社會2上C卷 第4卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "某國新任元首上任後，便開始修改制度，將原先分立的行政、立法、司法三權全數回收掌握在自己手中，取消民選元首制度，並隨意徵稅、利用人民的私有財產，搞得民不聊生，正面臨一股反對勢力。對於修法後該國政治現況，下列何者說明正確？", "o": ["權力節制互相制衡，人民權利受到保障", "施政备受民意監督，避免政府濫用權力", "人民可透過選舉，再次政權和平轉移", "權力因過度集中，恐導致政府濫用權力"], "a": 3, "e": "權力集中於一人、缺乏制衡，容易濫權、侵害人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-189", "no": 189, "c": "c2", "src": "114上翰林社會2上C卷 第4卷 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "權利是指在法律的保障之下，人民享有避免受到任意侵害且享有追求某種利益的權益。下列何者為「權利」的展現？", "o": ["年滿 18 歲的小完將入伍從事義務役", "訴訟被告警告阿昶向校方請求更正", "執行勤務的警察阿國在路口交通管制", "戶政機關限制民眾更改姓名超過三次"], "a": 1, "e": "依法向校方請求更正是行使權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-190", "no": 190, "c": "c3", "src": "114上翰林社會2上C卷 第4卷 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "有關現代國家建制實施「權力分立」的特色及目的，下列說法何者正確？", "o": ["讓施政有效能並避免專權", "讓人民可以參與國家事務", "為了擴大統治者的權力", "為了仲裁公平正義"], "a": 0, "e": "權力分立讓施政有效能並避免專權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-191", "no": 191, "c": "c4", "src": "114上翰林社會2上C卷 第4卷 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國現行的五權分立制度，是參考西方三權分立而來，絕大部分西方國家中央政府的分權方式仍採取「三權分立」原則。上述所說的三權為何？", "o": ["生存、工作和財產權", "請願、訴願和訴訟權", "行政、立法和司法權", "立法、考試和監察權"], "a": 2, "e": "三權是行政、立法、司法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-192", "no": 192, "c": "c3", "src": "114上翰林社會2上C卷 第4卷 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "英國學者艾克頓說：「權力使人腐化，絕對的權力，絕對的腐化。」現代國家為了避免權力集中造成過度濫權，多採取何種機制？", "o": ["專權政治", "中央集權", "權力分立", "世襲制度"], "a": 2, "e": "為避免權力集中濫權，採權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-193", "no": 193, "c": "c5", "src": "114上翰林社會2上C卷 第4卷 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "小儀：「你要不要去拜託你叔叔？他不是在那個裡面擔任主管職務？」小知：「不行啦，現在行政機關招考新進人員，都要透過國家考試。」根據上述對話，可知我國的政府體制，可避免何種問題發生？", "o": ["濫用私人", "專權政治", "人治社會", "議會專制"], "a": 0, "e": "行政機關招考新人須經國家考試，可避免濫用私人。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-194", "no": 194, "c": "c3", "src": "114上翰林社會2上C卷 第4卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "由於絕對的權力，可能會造成絕對的腐化，下列何人所在的國家，最能避免上述情況？", "o": ["小呂：我國將政權集中在領導一人手上", "小治：我國中央政府分為行政、立法、司法機關", "小中：我國由單一政府機關主導所有權力", "小和：全體沒有任何機關可以制衡行政機關"], "a": 1, "e": "中央政府分為行政、立法、司法機關，權力分立，可避免權力集中腐化。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-195", "no": 195, "c": "c1", "src": "114上翰林社會2上C卷 第4卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "法治是現代社會的重要概念，臺灣有上萬條現行法條規範生活中的事情。關於法治的敘述，何者正確？", "o": ["人民的權利受到基本保障", "法律無法約束政府的權力", "只要有制定法律就是法治社會", "統治者可依自身喜好制定法律"], "a": 0, "e": "法治社會中人民的權利受到基本保障。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-196", "no": 196, "c": "c5", "src": "114上翰林社會2上C卷 第4卷 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "來自臺灣的小葵參加一場國際學生交流活動，會中四名分屬不同國家的拓展分享各自國內的政治現況，下列何者最可能是小葵的發言？", "o": ["我國的人民沒有參與政治的機會", "我國的國家只有行政、立法、司法三權", "我國的國家領導人是由政黨推舉直接產生", "我的父親通過由考試院辦理的國家考試，進入中央政府任職"], "a": 3, "e": "通過考試院辦理的國家考試進入政府，是我國五權分立的特色。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-197", "no": 197, "c": "c5", "src": "114上翰林社會2上C卷 第4卷 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "提示一：代表民意，監督政府施政，制定重大法案。提示二：孫中山為避免此權力過大，將其分立，藉以健全政務體系。依據上述兩項提示，應是下列哪兩項政府權力？", "o": ["行政權、立法權", "立法權、考試權", "監察權、考試權", "立法權、監察權"], "a": 3, "e": "代表民意、監督政府、制定法案是立法權；孫中山將監察權從中分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-198", "no": 198, "c": "c4", "src": "114上翰林社會2上C卷 第4卷 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "2020 年美國新冠肺炎疫情嚴峻，國會 3 月底通過史上最大規模的經濟紓困措施，提供 2 兆億美元對抗經濟衝擊。上述的「國會」行使哪一種權力？", "o": ["立法權", "行政權", "司法權", "考試權"], "a": 0, "e": "國會通過紓困法案，行使立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-199", "no": 199, "c": "c5", "src": "114上翰林社會2上C卷 第4卷 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "孫中山在我國建國之初，針對三權分立的理論，結合當時的社會狀況，提出相關分析，下列何者正確？", "o": ["監察部門掌理人事任命容易濫用私人", "行政部門執行政策，易產生國會專制", "行政兼有考試權，易衍生用人弊端", "司法權易受權力牽絆，無法公正"], "a": 2, "e": "三權分立中行政兼有考試權，易衍生用人弊端。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-200", "no": 200, "c": "c1", "src": "114上翰林社會2上C卷 第4卷 第 1 題", "st": "考卷", "ctx": "以下是有關司法院釋憲案第 603 號解釋懶人包：一、內政部提案修改《戶籍法》第 8 條，希望藉由換發新式身分證機會強制按捺指紋存檔。二、立法委員連署向司法院提出該案釋憲，經審理認定《戶籍法》第 8 條違憲，立即失效。三、該案確認以《憲法》第 22 條為依據，民眾享有資訊自決權，避免政府濫用民眾個資。", "fig": "", "q": "依據上文第一項敘述，我國政府管理人民是採取何種模式？", "o": ["專制", "人治", "法治", "極權統治"], "a": 2, "e": "內政部依法修法、民眾權利受法律保障，是法治。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-201", "no": 201, "c": "c5", "src": "114上翰林社會2上C卷 第4卷 第 4 題", "st": "考卷", "ctx": "「亞森國」原是一個世襲君王且權力集中的國家，在民主思潮下，國王同意讓出政權，由人民選出政府，且為了避免新政府因權力集中所造成之專斷專橫，採用孫中山的權力分立理論，制定了國家的新憲法。", "fig": "", "q": "依據上述，該國新憲法採用孫中山的權力分立理論，是屬於下列何種制度？", "o": ["五權分立", "三權分立", "中央集權", "聯邦國家"], "a": 0, "e": "採用孫中山的權力分立理論，是五權分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-202", "no": 202, "c": "c2", "src": "114上翰林社會2上C卷 第6卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "為了有效運作並妥善分配國家資源，維持社會秩序，政府被賦予一定的支配力量，使其能執行各項公共事務。這種力量稱為何者？", "o": ["權利", "權力", "義務", "責任"], "a": 1, "e": "政府被賦予的支配力量稱為權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-203", "no": 203, "c": "c3", "src": "114上翰林社會2上C卷 第6卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "分權制衡制度，是透過權力分立後，權力間彼此相互牽制，以避免因濫權而侵害人民權利。下列有關我國分權制衡的敘述，何者正確？", "o": ["司法權受立法權監督", "總統可兼任行政院院長", "立法院得對行政院院長提出不信任案", "立法院須向行政院提出施政報告"], "a": 2, "e": "立法院可對行政院院長提出不信任案，是分權制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-204", "no": 204, "c": "c1", "src": "114上翰林社會2上C卷 第6卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "為了避免統治者過度濫權，許多國家施行法治概念，政府須依法行政，避免侵害人民權利。有關法治社會的敘述，何者正確？", "o": ["法律限制統治者權力", "執法無須有明確依據", "統治者可隨意更改法律", "統治者的意思就是法律"], "a": 0, "e": "法治社會以法律限制統治者的權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-205", "no": 205, "c": "c2", "src": "114上翰林社會2上C卷 第6卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據《警察職權行使法》規定：「警察行使職權時，應著制服或出示證件表明身分，並告知事由。……」小羚遇一名便衣警察臨檢，但對方未出示證件，因此小羚拒絕受檢。小羚的做法是保障自己的何項權益？", "o": ["權力", "權利", "義務", "責任"], "a": 1, "e": "小羚拒絕未出示證件的便衣警察臨檢，是保障自己的權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-206", "no": 206, "c": "c3", "src": "114上翰林社會2上C卷 第6卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "為了避免統治者專權，現代多數國家採取一項措施，將國家各種權力分散，並希望各權力間相互牽制，保持權力的平衡。上述措施為何？", "o": ["專權政治", "主權在民", "權力分立", "依法行政"], "a": 2, "e": "將權力分散並相互牽制，是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-207", "no": 207, "c": "c3", "src": "114上翰林社會2上C卷 第6卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "小納說明某一段政權概念時指出：「古代有篡位取得君權者，近代則有利用政變取得政權的統治者。若上述事件發生在今日，以現代民主政治運作的角度觀察，這些政治權力的來源其實都不具合法性。」小納的說法是因為上述兩種政權的來源皆缺乏哪一條件？", "o": ["政黨政治的發展", "人民自由的保障", "依法行政的政治涵養", "國家的主權來自人民"], "a": 3, "e": "篡位、政變取得的政權不合法，因為缺乏「國家主權來自人民」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-208", "no": 208, "c": "c5", "src": "114上翰林社會2上C卷 第6卷 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "為了避免政府專權，孫中山自孟德斯鳩的理論中設計出現行的憲政體系。有關我國現階段各院的職權及相關敘述，下列何者正確？", "o": ["考試委員由考試院選拔", "司法院審理法律違憲審查", "監察院可提出不信任案", "行政院行使人事同意權"], "a": 1, "e": "司法院大法官負責法律違憲審查。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-209", "no": 209, "c": "c5", "src": "114上翰林社會2上C卷 第6卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "「球證、旁證、技術委員、主辦、協辦，所有單位都是我的人。你們怎麼跟我鬥！」以上是電影《少林足球》的經典台詞。現實生活中，為了避免應聘過程產生類似的弊端，我國的政府體制特別將考試權從哪一項權力中獨立出來？", "o": ["行政權", "立法權", "司法權", "監察權"], "a": 0, "e": "為避免任用私人，將考試權從行政權獨立出來。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-210", "no": 210, "c": "c6", "src": "金安版公民(三) 第4次練習 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "在民主國家中，通常是藉由下列哪一項法律，以保障人民的基本權利？", "o": ["《民法》", "《刑法》", "《憲法》", "《國籍法》"], "a": 2, "e": "民主國家以《憲法》保障人民基本權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-211", "no": 211, "c": "c3", "src": "金安版公民(三) 第4次練習 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "右表為憲政研究社四位社員對於「權力分立」理論的說法，何人的見解正確？\n大佑：「國家將各種功能的能力加以集中給某個政府機關」\n丁安：「『權力分立』制度可降低政府施政效率」\n岑光：「限制人民權利的措施」\n苡晴：「避免政府濫權，危害人民的權利」", "o": ["大佑", "丁安", "岑光", "苡晴"], "a": 3, "e": "權力分立是為了避免政府濫權、侵害人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-212", "no": 212, "c": "c4", "src": "金安版公民(三) 第4次練習 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "西方的「三權分立」制度中，其行政權是負責下列何種職務？", "o": ["審查政府預算", "監督行政機關", "執行政策", "制定法律"], "a": 2, "e": "三權分立中行政權負責執行政策。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-213", "no": 213, "c": "c5", "src": "金安版公民(三) 第4次練習 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "孫中山先生倡導「五權分立」學說，他認為要為國家公正舉才，必須將下列何者獨立出來？", "o": ["司法權", "考試權", "立法權", "監察權"], "a": 1, "e": "為公正舉才，將考試權獨立出來。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-214", "no": 214, "c": "c4", "src": "金安版公民(三) 第4次練習 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "美國將三權分立的理念放入憲法之中，成為世界上最早實施三權分立的國家，主要是基於下列何種目的？", "o": ["擴張政府權力", "擴張國家主權", "集中國家各機關的權力", "政府權力相互制衡以保障人權"], "a": 3, "e": "美國實施三權分立，是為了讓政府權力相互制衡以保障人權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-215", "no": 215, "c": "c6", "src": "金安版公民(三) 第4次練習 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國藉由權力分立的原則，將政府的權力畫分給不同的機關，使其相互制衡，建構下列何種政府，才能真正落實保障人民基本權利的核心價值？", "o": ["無限政府", "有限政府", "集權政府", "無能政府"], "a": 1, "e": "權力分立可建構有限政府。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-216", "no": 216, "c": "c2", "src": "金安版公民(三) 第4次練習 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "權力和權利兩者並不相同。右表中，何者是屬於「權利」？\n(甲)法官將殺人犯判處死刑\n(乙)警察取締飆車族\n(丙)一群人參與「反貪腐」的遊行\n(丁)新北市長推行「路平專案」", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "人民參與遊行是行使權利；其他是政府行使權力。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-217", "no": 217, "c": "c3", "src": "金安版公民(三) 第4次練習 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "國防部長到立法院針對「潛艦國造」政策做施政報告，並接受立法委員的質詢。上述情形最可用下列哪種憲政精神來形容？", "o": ["權力分立", "法治政治", "主權在民", "違憲審查制度"], "a": 0, "e": "國防部長到立法院報告並接受質詢，是行政與立法分立制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-218", "no": 218, "c": "c5", "src": "金安版公民(三) 第4次練習 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "右表以我國政府機關為例，甲、乙依序應填入下列何者？\n總統府掌管：甲權\n立法院掌管：乙權", "o": ["監察、立法", "行政、立法", "行政、司法", "立法、司法"], "a": 1, "e": "總統府掌管行政權，立法院掌管立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-219", "no": 219, "c": "c1", "src": "金安版公民(三) 第4次練習 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "法治社會與人治社會中，對於法律的目的有所不同，右表中哪二者是屬於法治社會中的法律目的？\n(甲)鞏固統治者的權力\n(乙)限制人民的工具\n(丙)限制政府的權力\n(丁)保障人民的權利", "o": ["甲乙", "甲丁", "乙丙", "丙丁"], "a": 3, "e": "法治社會的法律目的是限制政府權力、保障人民權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-220", "no": 220, "c": "c6", "src": "金安版公民(三) 第4次練習 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列為維德整理公民筆記上的重點：\n(1)嚴格保護人民的財產權、自由權和生存權。\n(2)推行市場經濟制度，反對政府過多干預經濟發展。\n(3)實行權力分立與制衡的政治制度。依此判斷，下列何者最有可能是筆記的標題？", "o": ["憲法的權利保障", "有限政府的特色", "人民與政府的權限劃分", "三權與五權分立的差異"], "a": 1, "e": "保障人民權利、反對政府過度干預、權力分立制衡，是有限政府的特色。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-221", "no": 221, "c": "c1", "src": "金安版公民(三) 第4次練習 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "法治社會與人治社會中，對於法律的約束力有所不同，下列何者是「人治社會」的特徵？", "o": ["法律只約束統治者不約束人民", "法律同時不能約束統治者與人民", "統治者與人民同時受法律的約束", "統治者不需遵守法律，法律只約束人民的行為"], "a": 3, "e": "人治社會中統治者不需遵守法律，法律只約束人民。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-222", "no": 222, "c": "c2", "src": "金安版公民(三) 第4次練習 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列中，乙是現代法治國家的兩個軸心，根據內容判斷，甲、乙依序為下列何者？\n甲：是支配的力量\n乙：是人民所應享有的生活利益", "o": ["權力、權利", "權利、權力", "主權、公權力", "政權、公權力"], "a": 0, "e": "甲是支配的力量（權力），乙是人民的生活利益（權利）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-223", "no": 223, "c": "c3", "src": "金安版公民(三) 第4次練習 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列為張老師講述某名詞引用說明的資料。依此判斷，最可能是下列哪一個名詞？\n說明資料：＊避免政局專權統治。＊追求政府效率。＊使政府權力平衡，不侵害人民權利。", "o": ["君主專制", "主權在民", "權力分立", "依法行政"], "a": 2, "e": "避免專權、使權力平衡，是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-224", "no": 224, "c": "c1", "src": "金安版公民(三) 第4次練習 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "有關法治社會中的政府，下列敘述何者正確？", "o": ["政府可隨意變更法律", "政府只是法律的執行者", "政府制定法律並可擴大其權力", "政府可任意以法律侵害人民的權利"], "a": 1, "e": "法治社會中政府只是法律的執行者，不能任意變更法律。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-225", "no": 225, "c": "c4", "src": "金安版公民(三) 第4次練習 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列為報紙報導西方「三權分立」學說所編製的示意圖。依內容判斷，何者正確？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "丙：司法權（法院）依據法律獨立行使職權，說法正確；三權應相互制衡，不是「權力集中、相互合作」。依原卷答案為 (C)。", "rep": false, "img": "c3-q225", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-226", "no": 226, "c": "c4", "src": "金安版公民(三) 第4次練習 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "從民主國家設計「權力分立」的政府架構來看，下列哪一個機關是《憲法》的守護神，將使《憲法》轉換為對政府權力的實質約束，以保障人民權利？", "o": ["立法機關", "監察機關", "司法機關", "行政機關"], "a": 2, "e": "司法機關可審查法律是否違憲，是《憲法》的守護神。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-227", "no": 227, "c": "c1", "src": "金安版公民(三) 第4次練習 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "警察取締微型電動二輪車，必須依據新修正的《道路交通管理處罰條例》的規定，凡是無掛車牌或無投保責任險者，騎車上路才可以開立罰單。這是在彰顯下列何種精神？", "o": ["分權制衡", "民意政治", "依法行政", "政黨政治"], "a": 2, "e": "警察開罰單必須依據法律規定，是依法行政。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-228", "no": 228, "c": "c3", "src": "金安版公民(三) 第4次練習 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "第 2 條規定：總統為避免國家或人民遭遇緊急危難或應付財政經濟上重大變故，得經行政院會議之決議發布緊急命令……，十日內提交立法院追認，如立法院不同意時，該緊急命令立即失效。上述為張老師說明憲政精神內涵時，引用《憲法增修條文》做說明。此內容主要在講述何種內涵？", "o": ["法治政治", "權力分立", "主權在民", "政黨輪替"], "a": 1, "e": "緊急命令由總統發布、須經行政院會議決議並由立法院追認，權力分立制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-229", "no": 229, "c": "c4", "src": "金安版公民(三) 第4次練習 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "若依據西方「三權分立」的理論，目前兩位美國總統與美國國會，依序代表哪一項權力？", "o": ["行政權、立法權", "行政權、司法權", "立法權、行政權", "司法權、行政權"], "a": 0, "e": "美國總統代表行政權，國會代表立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-230", "no": 230, "c": "c2", "src": "金安版公民(三) 第4次練習 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "權力與權利是現代法治國家的兩個軸心，右列項目中的甲、乙依序是屬於下列何者？\n甲：請你配合我依法進行酒駕的臨檢\n乙：我有騎乘機車的自由，你不能干涉我", "o": ["權利、權力", "權力、權利", "皆為權力", "皆為權利"], "a": 1, "e": "甲：警察依法臨檢是權力；乙：人民騎車的自由是權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-231", "no": 231, "c": "c6", "src": "金安版公民(三) 第4次練習 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "民主國家必須依據憲政精神實行憲政，並以《憲法》治理國家。下列何者為「憲政精神」的內涵？", "o": ["防止人民濫權", "建構一個龐大而有為的政府", "《憲法》規範政府權力的擴張性與明確性", "將政府的權力與運作方式納入《憲法》的規範"], "a": 3, "e": "憲政精神是將政府權力與運作方式納入《憲法》規範。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-232", "no": 232, "c": "c5", "src": "金安版公民(三) 第4次練習 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "五權分立為我國獨特的中央政府體制，孫中山為了革除右圖三權分立的哪一個缺點，以杜絕國會的專制？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "孫中山為杜絕國會專制，針對立法權兼監察權的缺點，將監察權獨立。", "rep": false, "img": "c3-q232", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-233", "no": 233, "c": "c5", "src": "金安版公民(三) 第4次練習 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國採用「五權分立」的理論，傳統的科舉制度是甲權的行使，御史大夫是乙權的行使，這兩個權力機構是中國有別於西方主張權力分立的政府機構，孫中山先生主張應獨立出來。上述甲、乙依序應填入下列何者？", "o": ["監察、司法", "監察、考試", "考試、司法", "考試、監察"], "a": 3, "e": "科舉是考試權、御史大夫是監察權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-234", "no": 234, "c": "c3", "src": "金安版公民(三) 第4次練習 第 25 題", "st": "考卷", "ctx": "", "fig": "", "q": "英國歷史學家艾克頓爵士的名言：「權力使人腐化，絕對的權力，絕對的腐化。」下列何者的敘述最能彰顯出該名言的涵義？", "o": ["造成一個擴權的政府", "政府間的權力運作不必使其相互制衡", "唯有無能的政府，才不會使政府的權力腐化", "權力不能集中在同一群人手中，以免權力被濫用"], "a": 3, "e": "艾克頓的名言表示權力不能集中在同一群人手中。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-235", "no": 235, "c": "c4", "src": "金安版公民(三) 第4次練習 第 26 題", "st": "考卷", "ctx": "在新冠肺炎疫情嚴峻的時期，我國政府管制國內口罩的生產量及販售，有立法委員在立法院開會時，向行政院衛生福利部部長針對推動的口罩政策提出質詢，要求改善並符合民眾的需求。衛生福利部部長也基於回覆的責任向立法委員報告，口罩政策已從「實名制 1.0」實體通路購買，接著「實名制 2.0」的健保快易通 APP 及網站購買，到「實名制 3.0」超商預購，民眾大排長龍購買口罩的情形，很快就會改善。", "fig": "", "q": "立法委員在立法院會議，監督行政院官員的施政。依內容判斷，我國立法院的性質最類似於下列西方國家的哪一種機關？", "o": ["法院", "內閣", "國會", "元首官邸"], "a": 2, "e": "立法院監督行政院，性質類似西方的國會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-236", "no": 236, "c": "c3", "src": "金安版公民(三) 第4次練習 第 27 題", "st": "考卷", "ctx": "在新冠肺炎疫情嚴峻的時期，我國政府管制國內口罩的生產量及販售，有立法委員在立法院開會時，向行政院衛生福利部部長針對推動的口罩政策提出質詢，要求改善並符合民眾的需求。衛生福利部部長也基於回覆的責任向立法委員報告，口罩政策已從「實名制 1.0」實體通路購買，接著「實名制 2.0」的健保快易通 APP 及網站購買，到「實名制 3.0」超商預購，民眾大排長龍購買口罩的情形，很快就會改善。", "fig": "", "q": "根據上文中「立法委員向衛福部部長提出質詢、部長基於回覆的責任向立委報告」判斷，其主要在表現民主國家的哪一種精神？", "o": ["法治政治", "權力分立", "人治社會", "主權在民"], "a": 1, "e": "立法委員質詢、部長回覆，是行政與立法分立制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-237", "no": 237, "c": "c5", "src": "金安版公民(三) 第4次練習 第 28 題", "st": "考卷", "ctx": "公民老師在講授完「權力分立」的學說後，於黑板上畫了三權（甲）與五權（乙）分立的簡易說明圖，藉此來釐清學生對該主題的重點及其差異。", "fig": "", "q": "圖中甲和乙的差別，在於哪二權？", "o": ["行政權、立法權", "立法權、司法權", "司法權、考試權", "考試權、監察權"], "a": 3, "e": "三權分立與五權分立的差別在考試權、監察權。", "rep": true, "img": "c3-q237", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-238", "no": 238, "c": "c5", "src": "金安版公民(三) 第4次練習 第 29 題", "st": "考卷", "ctx": "公民老師在講授完「權力分立」的學說後，於黑板上畫了三權（甲）與五權（乙）分立的簡易說明圖，藉此來釐清學生對該主題的重點及其差異。", "fig": "", "q": "提出甲理論的學者，是基於乙理論有下列何項缺陷，而改良的政治制度？", "o": ["行政權兼考試權造成濫用私人", "行政權兼監察權造成議會專制", "立法權兼監察權造成濫用私人", "立法權兼考試權造成議會專制"], "a": 0, "e": "孫中山認為三權分立中行政權兼考試權會造成濫用私人。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-239", "no": 239, "c": "c4", "src": "金安版公民(三) 第4次練習 第 30 題", "st": "考卷", "ctx": "公民老師在講授完「權力分立」的學說後，於黑板上畫了三權（甲）與五權（乙）分立的簡易說明圖，藉此來釐清學生對該主題的重點及其差異。", "fig": "", "q": "公民老師要求學生舉出與該理論有關的例子，下列何人的舉例正確？", "o": ["美麗：臺北市政府依法對違反食安法的店家祭出高額罰款", "君如：美國白宮要求國會通過撥款數百億美元援助烏克蘭", "瑞明：我國定期每四年就要選出中央或地方的各公職人員", "永彰：政府政策失誤導致人民權益受損，引致民怨，政府官員辭職下臺"], "a": 1, "e": "美國白宮（行政）要求國會（立法）通過撥款，是三權分立下機關的分工制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-240", "no": 240, "c": "c1", "src": "金安版公民(三) 第6次練習 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "人治與法治社會有所區別，而下列何者是「法治社會」的特徵？", "o": ["政府可不必依法行政", "統治者的意思就是法律", "法律制定的目的在限制人民的權利", "法律可同時約束政府與人民的行為"], "a": 3, "e": "法治社會中法律同時約束政府與人民。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-241", "no": 241, "c": "c3", "src": "金安版公民(三) 第6次練習 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "「權力分立」以以信國家的主權屬於全體國民。大雄：「政府依據法律明文規定行使職權。」光仁：「將國家的權力集中於某一機關，可以提升政府的效力。」友諒：「將政府權力分散成不同機關，使其相互制衡，建立有限政府。」四人的說法，何者最能彰顯出「權力分立」的原則？", "o": ["以信", "大雄", "光仁", "友諒"], "a": 3, "e": "將政府權力分散、相互制衡、建立有限政府，最能彰顯權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-243", "no": 243, "c": "c4", "src": "金安版公民(三) 第6次練習 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "公民老師上完課後，有四位同學在課餘時間討論「三權分立」的內涵，下列何者的說法錯誤？\n安安：「行政機關負責執行政策。」\n健健：「行政、立法、司法三者相互制衡。」\n宇豪：「司法機關依法獨立，可影響立法、行政權。」\n廷廷：「立法機關制定法律、監督行政機關。」", "o": ["安安", "健健", "宇豪", "廷廷"], "a": 2, "e": "司法機關依法獨立，用以制衡立法與行政，不是「影響」它們。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-244", "no": 244, "c": "c4", "src": "金安版公民(三) 第6次練習 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "孟德斯鳩的權力分立學說，主張 甲 掌握行政權，負責執行政策， 乙 掌握立法權，審查政府預算。上述甲、乙二者依序為下列何者？", "o": ["內閣、法院", "國會、法院", "國會、內閣", "內閣、國會"], "a": 3, "e": "三權分立中內閣掌握行政權、國會掌握立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-245", "no": 245, "c": "c5", "src": "金安版公民(三) 第6次練習 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖是大山報告「三權分立學說」的內容及其缺點，所繪製的圖表。根據圖中內容判斷，下列何者正確？", "o": ["甲：司法權，乙：行政權", "甲：行政權，乙：立法權", "乙：立法權，丙：行政權", "甲：司法權，丙：立法權"], "a": 2, "e": "乙兼監察權→國會專制，是立法權；丙兼考試權→濫用私人，是行政權（依原卷答案為 C）。", "rep": false, "img": "c3-q245", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-246", "no": 246, "c": "c3", "src": "金安版公民(三) 第6次練習 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "英國著名歷史學家艾克頓爵士名言：「權力使人腐化，絕對的權力，絕對的腐化。」為避免此種情形的發生，現代國家對於中央政府體制的設計必須具備「這種特質」較為適宜。上列是江老師在黑板所書寫的資料。依內容判斷，江老師所指的「這種特質」是指下列何者？", "o": ["國家權力集中", "分權制衡", "高能政府", "專權政治"], "a": 1, "e": "為避免權力使人腐化，政府體制必須分權制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-300", "no": 300, "c": "c3", "src": "試題寶典評量第 24 頁 基礎實力題 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "英國歷史學家艾克頓爵士曾說：「權力使人腐化，絕對的權力，絕對的腐化。」下列何者符合其所要表達的意義？", "o": ["在政府機關工作的官員都是獨裁者", "權力既然使人腐化，所以政府就不該擁有權力", "權力的分散容易為社會帶來不安", "政治權力不能過度集中，以免權力被濫用"], "a": 3, "e": "權力過度集中容易被濫用，所以要分散權力、相互制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-301", "no": 301, "c": "c3", "src": "試題寶典評量第 24 頁 基礎實力題 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "絕對的權力易導致絕對的腐化，所以民主國家之中央政府體制的設置，大多以權力分立為原則，主要是為了達到何種目的？", "o": ["互相制衡", "絕對專制", "互相鬥爭", "互相反對"], "a": 0, "e": "權力分立的目的是讓各機關互相制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-302", "no": 302, "c": "c4", "src": "試題寶典評量第 24 頁 基礎實力題 第 12 題", "st": "講義", "ctx": "", "fig": "", "q": "西方國家所採用的三權分立學說是由誰所提倡？", "o": ["洛克", "孫中山", "艾克頓", "孟德斯鳩"], "a": 3, "e": "三權分立學說由法國思想家孟德斯鳩提出。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-303", "no": 303, "c": "c3", "src": "試題寶典評量第 24 頁 基礎實力題 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "在現代民主國家中多將各種功能的權力交由不同機關執行，下列何者不是實施權力分立的目的？", "o": ["分散權力相互牽制", "避免專權政治", "集中國家權力以保護人民權利", "保持權力平衡的狀態"], "a": 2, "e": "權力分立是要避免國家權力過度集中而侵害人民權利，不是集中權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-304", "no": 304, "c": "c3", "src": "試題寶典評量第 24 頁 基礎實力題 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "現代國家對於中央政府體制的設計，為了達到分權制衡的目的，多以下列何者為原則？", "o": ["權力集中", "權力分立", "議會專權", "政府無權"], "a": 1, "e": "以權力分立為原則，達到分權制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-305", "no": 305, "c": "c6", "src": "試題寶典評量第 24 頁 基礎實力題 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "許多國家為了防止政府濫權，維護人民的自由與權利，會建構何種政府？", "o": ["有限政府", "無限政府", "極權政府", "專制政府"], "a": 0, "e": "有限政府的權力受《憲法》與法律限制，可防止濫權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-306", "no": 306, "c": "c4", "src": "試題寶典評量第 24 頁 精熟思考題 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "「三權分立」是當前全球多數國家所採行的政治制度，有關三權分立的敘述，下列何者正確？", "o": ["用來限制人民權利、保障國家權力", "是指行政、立法、司法三種權力", "其學說是英國哲學家洛克所提倡", "我國政治制度採用三權分立"], "a": 1, "e": "(A)應是保障人民權利、限制國家權力；(C)由法國孟德斯鳩提出；(D)我國採五權分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-307", "no": 307, "c": "c1", "src": "試題寶典評量第 24 頁 精熟思考題 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "「法治」是現代社會所強調的重要概念，我國奉行法治和民主制度，目前現行的法條已有上萬條之多，規範著生活中許多大大小小的事情。下列關於我國「法治」的敘述，何者正確？", "o": ["法律是由少數政治人物所決定", "總統可依照自身喜好制定法律", "人民的權利可受到基本的保障", "法律無法約束政府的行政職權"], "a": 2, "e": "法治社會中，人民權利可受到法律保障。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-308", "no": 308, "c": "c1", "src": "試題寶典評量第 24 頁 精熟思考題 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "在人治社會中，統治者的權力通常不受法律約束，且可以根據自己的意志來做出決策。上述的社會特徵最可能帶來哪一問題？", "o": ["法律平等適用於每個人", "社會的穩定性較強", "權力過度集中，容易產生濫權行為", "每個人都可以參與政治決策"], "a": 2, "e": "統治者依自己的好惡統治人民，權力集中容易濫權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-309", "no": 309, "c": "c3", "src": "試題寶典第 40 頁 第二次段考模擬試題 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "權力分立用於政府的體制上有多種形式，下列有關權力分立的敘述何者錯誤？", "o": ["可以讓政府的權力無限擴大", "是指權力機關的制衡", "西方國家主要是行政、立法、司法三權分立", "可以防止政府因權力集中而出現的濫權"], "a": 0, "e": "權力分立是為了建立有限政府，不是讓政府權力無限擴大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-310", "no": 310, "c": "c3", "src": "114上翰林社會2上A卷 卷4 題組 (一) 1", "st": "考卷", "ctx": "2024 年 8 月，宜蘭地方法院法官因違反交通規則被警察攔查，因酒測值有超標，經審判後被判處有期徒刑，司法院也將其停職。監察委員認為該名法官違反《公務員服務法》及法官倫理規範，情節重大，亦對其提出彈劾，移送懲戒法庭審理。", "fig": "", "q": "針對上文提到的公職人員，下列說明何者正確？", "o": ["警察有任意攔查車輛的權力", "法官有依法獨立審判的權利", "監察委員隸屬立法機關", "法庭審理歸司法機關"], "a": 3, "e": "法庭審理屬司法機關。(A)警察須依法攔查；(B)獨立審判是法官的「權力」；(C)監察委員屬監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-311", "no": 311, "c": "c1", "src": "114上翰林社會2上A卷 卷4 題組 (一) 2", "st": "考卷", "ctx": "2024 年 8 月，宜蘭地方法院法官因違反交通規則被警察攔查，因酒測值有超標，經審判後被判處有期徒刑，司法院也將其停職。監察委員認為該名法官違反《公務員服務法》及法官倫理規範，情節重大，亦對其提出彈劾，移送懲戒法庭審理。", "fig": "", "q": "從上述案件分析我國的體制，下列說明何者錯誤？", "o": ["符合人治社會", "實施權力分立", "政府依法行政", "落實責任政治"], "a": 0, "e": "法官違法同樣受法律制裁，是法治社會，不是人治。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-312", "no": 312, "c": "c1", "src": "114上翰林社會2上A卷 卷4 題組 (二) 3", "st": "考卷", "ctx": "美國總統候選人賀錦麗與其所屬的民主黨皆敗選，她發表演說：「我已致電恭賀川普勝選，並承諾將政權和平移交。美國民主的原則就是『選舉輸了就要接受這個結果』，正是這個原則讓民主不同於君主制或暴君獨裁。然而，在美國，所有人都沒有義務效忠於總統或政黨，美國人的義務是效忠美國憲法，或會繼續為憲法所捍衛的自由、公平、機會和尊嚴而奮戰到底。」", "fig": "", "q": "上文中「所有人都沒有義務效忠於總統或政黨，美國人的義務是效忠美國憲法」這部分最能彰顯什麼核心價值？", "o": ["人治社會", "法治社會", "無限政府", "主權在民"], "a": 1, "e": "人人效忠憲法、法律至上，是法治社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-313", "no": 313, "c": "c4", "src": "114上翰林社會2上A卷 卷4 題組 (二) 4", "st": "考卷", "ctx": "美國總統候選人賀錦麗與其所屬的民主黨皆敗選，她發表演說：「我已致電恭賀川普勝選，並承諾將政權和平移交。美國民主的原則就是『選舉輸了就要接受這個結果』，正是這個原則讓民主不同於君主制或暴君獨裁。然而，在美國，所有人都沒有義務效忠於總統或政黨，美國人的義務是效忠美國憲法，或會繼續為憲法所捍衛的自由、公平、機會和尊嚴而奮戰到底。」", "fig": "", "q": "依據上文推測美國選後的政局發展，何者最符合權力分立的政府體制？", "o": ["川普成為總統，掌握行政與立法權", "川普掌握司法權，將政敵審判定罪", "民主黨掌握國會立法權，監督行政", "民主黨把持統治權，不讓政敵上位"], "a": 2, "e": "三權分立下，國會掌握立法權並監督行政；總統不能同時掌握立法、司法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-314", "no": 314, "c": "c6", "src": "114上翰林社會2上A卷 卷6 題組 (一) 1", "st": "考卷", "ctx": "2024 年 12 月 3 日晚上，韓國總統尹錫悅發布緊急命令，宣布即刻實施戒嚴，以應對「反國家勢力」及來自北韓的安全威脅。該國國會於凌晨 1 時迅速召開會議，通過解除戒嚴案。在野黨指責尹錫悅的行為構成嚴重內亂，戒嚴令也違憲，於是發動彈劾總統。國會通過總統彈劾案後，尹錫悅的總統職權被暫停，並由南韓憲法法院接手審理總統彈劾案。", "fig": "", "q": "由上文可知，韓國屬於下列哪一種制度？", "o": ["中央集權", "五權分立", "有限政府", "人治社會"], "a": 2, "e": "總統發布戒嚴後被國會解除、彈劾，權力受到限制，屬於有限政府。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-315", "no": 315, "c": "c2", "src": "114上翰林社會2上A卷 卷6 題組 (二) 3", "st": "考卷", "ctx": "某娛樂公司曾盛大舉辦三場名為「有趣的演講」的表演，門票收入超過二千萬，被臺北市稅捐處依《娛樂稅法》徵繳稅金 28 萬元，但該公司主張此活動為演講性質本就不必繳稅而提出訴願，被駁回後再提行政訴訟，高等行政法院仍認定該活動是喜劇性質而非演講，判處該公司敗訴，需依法繳稅。", "fig": "", "q": "分析上文中呈現出的權利與權力，下列何者正確？", "o": ["演講或表演是表現自由權力", "稅捐處具有依法收稅的權力", "提出訴願是人民行使參政權", "法院擁有依法律審判的權利"], "a": 1, "e": "稅捐處依法收稅是政府的權力。(A)表現自由是「權利」；(C)訴願是受益權；(D)審判是法院的「權力」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-316", "no": 316, "c": "c3", "src": "114上翰林社會2上A卷 卷6 題組 (二) 4", "st": "考卷", "ctx": "某娛樂公司曾盛大舉辦三場名為「有趣的演講」的表演，門票收入超過二千萬，被臺北市稅捐處依《娛樂稅法》徵繳稅金 28 萬元，但該公司主張此活動為演講性質本就不必繳稅而提出訴願，被駁回後再提行政訴訟，高等行政法院仍認定該活動是喜劇性質而非演講，判處該公司敗訴，需依法繳稅。", "fig": "", "q": "上文中「依法徵稅→民眾不服處分提出訴願→訴願失敗再提行政訴訟」，各環節權責機關都不同，符合哪一概念？", "o": ["權力分立", "中央集權", "政黨輪替", "無限政府"], "a": 0, "e": "由不同機關各司其職、相互制衡，是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-317", "no": 317, "c": "c5", "src": "114上翰林社會2上A卷 卷6 進階思考題 5", "st": "考卷", "ctx": "", "fig": "", "q": "阿民對比我國立法院與韓國國會規定，發現韓國有兩項重大差異：國政監察權——韓國國會每年都要對政府各部門的工作進行全面審查，確保政府行為符合法律和公共利益；彈劾追訴權——韓國國會有權對總統、總理、行政各部長官、法官或公務員等進行彈劾。根據內容分析兩國制度的差異，與何者最相關？", "o": ["我國將考試權從立法權中獨立", "我國將監察權從立法權中獨立", "韓國的行政部門可行使監察權", "韓國制度可改善國會專制濫權"], "a": 1, "e": "韓國國會兼有監察、彈劾權；我國依五權分立，將監察權從立法權中獨立出來，避免國會專制。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-318", "no": 318, "c": "c2", "src": "114上翰林社會2上A卷 卷6 進階思考題 6", "st": "考卷", "ctx": "", "fig": "", "q": "下列是某法律內容節錄：「第三條：參與犯罪組織者，處六月以上五年以下有期徒刑。第四條：招募他人加入犯罪組織者，處六月以上五年以下有期徒刑；以非法方式使他人加入，處一年以上七年以下有期徒刑。」若由該法規內容分析權利與權力，何者說明正確？", "o": ["人民有集會結社的權利，包括上述組織", "人民加入犯罪組織的權力受到法律約束", "警察依法有抓捕犯罪組織的權利和義務", "法官依法對組織犯罪行為有定罪的權力"], "a": 3, "e": "法官依法定罪是公權力（權力）。(A)犯罪組織不受保障；(B)人民的是「權利」不是權力；(C)警察抓人是「權力」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-319", "no": 319, "c": "c5", "src": "114上翰林社會2上B卷 卷6 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國古代社會設有「諫官」制度，其設置的目的是為規勸君主及彈劾違法失職的官員，並使其改正。若依我國《憲法》規定，「諫官」制度應是掌有政府的何種權力？", "o": ["司法權", "立法權", "監察權", "行政權"], "a": 2, "e": "彈劾違法失職官員屬監察權；孫中山參考中國古代監察制度，將監察權獨立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-320", "no": 320, "c": "c5", "src": "114上翰林社會2上C卷 卷4 進階思考題 1", "st": "考卷", "ctx": "", "fig": "", "q": "小禕參加政府體制牌卡桌遊，遊戲規則是只要拿到與題目相關的關鍵字牌卡，最多且正確的人即可得分。題目是「我國現行的政府體制」，下列何者蒐集的牌卡可得到最多分數？", "o": ["小禕：法治政治、有限政府、五權分立", "小晴：人治政治、有限政府、三權分立", "小中：法治政治、無限政府、三權分立", "小萱：人治政治、無限政府、五權分立"], "a": 0, "e": "我國是法治、有限政府，採五權分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-321", "no": 321, "c": "c2", "src": "114上翰林社會2上C卷 卷4 進階思考題 2", "st": "考卷", "ctx": "", "fig": "", "q": "權力是現代法治國家的軸心之一，下列何者屬於政府行使公權力的展現？", "o": ["小明向學務處申訴遭同學霸凌的情況", "小美透過健保制度減輕就醫時的經濟負擔", "小中拒絕警方在無正當理由下進行住家搜索", "教育局對無故缺課的中輟生家長開立裁罰通知"], "a": 3, "e": "政府機關依法開罰是公權力；其他是人民行使權利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-322", "no": 322, "c": "c3", "src": "114上翰林社會2上C卷 卷4 進階思考題 3", "st": "考卷", "ctx": "", "fig": "", "q": "孫中山在其著作中，提出權力集中的政府乃是萬惡之源，會做出許多侵害人民權利的事，因此必須將政府權力分散開來，並且還要互相監督。上述是指政府組織運作時，所應遵循的哪一項原則？", "o": ["主權在民", "法治政治", "權力分立", "政黨輪替"], "a": 2, "e": "將權力分散並互相監督，就是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-323", "no": 323, "c": "c4", "src": "114上翰林社會2上C卷 卷4 進階思考題 4", "st": "考卷", "ctx": "", "fig": "", "q": "填字遊戲：直的提示——1：孟德斯鳩提出的權力分立原則；2：人民有避免受到任意侵害或追求利益的權益。橫的提示——一：孫中山提出的權力分立制度；二：具有優勢資源，可強制分配的力量。直 1 應填入下列何者？", "o": ["五權分立", "三權分立", "政黨輪替", "依法行政"], "a": 1, "e": "孟德斯鳩提出三權分立。（直2權利、橫一五權分立、橫二權力）", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-324", "no": 324, "c": "c4", "src": "114上翰林社會2上C卷 卷4 進階思考題 5", "st": "考卷", "ctx": "", "fig": "", "q": "美國是第一個實行三權分立的國家，關於三權之間的相互制衡，下列何者正確？", "o": ["行政機關監督立法機關的政策執行", "行政機關須向司法機關提交施政報告", "當法律可能違憲時，由國會負責進行解釋", "司法機關可透過獨立審判制衡行政權與立法權"], "a": 3, "e": "司法機關獨立審判，以法制衡行政與立法；是立法機關監督行政，法律是否違憲由法院判斷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-325", "no": 325, "c": "c4", "src": "114上翰林社會2上C卷 卷4 進階思考題 6", "st": "考卷", "ctx": "", "fig": "", "q": "下列是幾位同學在討論三權分立制度，何者的說法正確？", "o": ["彬彬：利用行政權來監督立法權", "朝朝：考試權獨立避免用人弊端", "沈沈：司法獨立制衡行政與立法", "曾曾：監察權獨立避免國會濫權"], "a": 2, "e": "三權分立中司法獨立制衡行政與立法。(B)(D)是五權分立的特色。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c3-map-powers"], "chk": ""}, {"id": "c3-326", "no": 326, "c": "c4", "src": "114上翰林社會2上C卷 卷4 進階思考題 7", "st": "考卷", "ctx": "", "fig": "", "q": "現今許多民主國家都設有總統（總理）、立法機關（國會）和各級法院，三者的權力彼此相互制衡。上述這種體制最早源自何人的思想？", "o": ["孫中山", "艾克頓", "麥迪遜", "孟德斯鳩"], "a": 3, "e": "行政、立法、司法三權分立源自孟德斯鳩。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-327", "no": 327, "c": "c6", "src": "114上翰林社會2上C卷 卷4 題組 2", "st": "考卷", "ctx": "以下是有關司法院釋憲案第 603 號解釋懶人包：一、內政部提案修改《戶籍法》第 8 條，希望藉由換發新式身分證機會強制按捺指紋存檔。二、立法委員連署向司法院提出該案釋憲，經審理認定《戶籍法》第 8 條違憲，立即失效。三、該案確認以《憲法》第 22 條為依據，民眾享有資訊自決權，避免政府濫用民眾個資。", "fig": "", "q": "依據上文第二項敘述，其最能彰顯《憲法》的哪一項特性？", "o": ["最高性", "固定性", "原則性", "不變性"], "a": 0, "e": "法律違憲即失效，顯示《憲法》具有最高性，政府權力受《憲法》限制。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-328", "no": 328, "c": "c4", "src": "114上翰林社會2上C卷 卷6 進階思考題 2", "st": "考卷", "ctx": "", "fig": "", "q": "雖然經常有人質疑臺灣的司法不公，但以分權制衡觀點來看，司法的確扮演著一股平衡力量，保障民眾的權益。關於司法權，下列何者敘述正確？", "o": ["最早由孟德斯鳩提出行政、司法、立法三權分立", "孫中山將司法權自行政權中獨立，避免行政濫權", "在臺灣，司法院大法官是由人民直選的司法人員", "司法權代表人民制定法律，並監督行政機關施政"], "a": 0, "e": "(B)孫中山獨立的是考試權、監察權；(C)大法官由總統提名、立法院同意；(D)制定法律是立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c3-329", "no": 329, "c": "c1", "src": "114上翰林社會2上C卷 卷6 題組 (二) 3", "st": "考卷", "ctx": "2020 年花蓮縣政府因受到地方居民的強力反彈，逕自將原有核准某養雞場營運的執照撤銷，該公司不滿無故遭撤照，提起相關行政程序救濟，經行政院農業部裁定，花蓮縣政府應將行政處分撤銷，避免行政機關濫用其行政權。", "fig": "", "q": "花蓮縣政府逕自將該養雞場營運的執照撤銷，未具相關依據，最終經中央裁定處分無效，此事顯示我國為何種治理特色？", "o": ["人治", "獨裁", "極權", "法治"], "a": 3, "e": "政府行政處分沒有法律依據就無效，政府也受法律約束，是法治。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}], "extras": [{"id": "compare", "title": "易混淆比較", "html": "<h3>1. 人治社會 vs 法治社會 比較表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>人治社會</th><th>法治社會</th></tr></thead><tbody><tr><td><b>治理核心理念</b></td><td>統治者依照<b>個人好惡與主觀意志</b>治理國家</td><td>人民與政府均須嚴格受到<b>法律約束</b>，法律面前人人平等</td></tr><tr><td><b>法律制定者</b></td><td>統治者自行決定（「<b>國王就是法律</b>」）</td><td>由<b>人民選出的民意代表</b>依法定程序制定</td></tr><tr><td><b>法律的主要目的</b></td><td>鞏固統治者統治地位、限制與控制人民的<b>工具</b></td><td><b>限制政府權力、防止公權力濫用、保障人民權利</b></td></tr><tr><td><b>法律拘束力對象</b></td><td><b>僅約束人民</b>；統治者享有特權，不需守法</td><td><b>同時約束政府與人民</b>；法律為全民共同最高準則</td></tr><tr><td><b>法律的穩定性</b></td><td>缺乏穩定性，隨統治者意志<b>朝令夕改</b>，人民無所適從</td><td>具備<b>明確性與穩定性</b>，人民可清楚預期自身行為之法律效果</td></tr><tr><td><b>政府執法原則</b></td><td>統治者隨心所欲，執法標準因人而異</td><td>行政機關必須嚴格恪遵「<b>依法行政</b>」原則</td></tr><tr><td><b>典型歷史或時事代表</b></td><td>古代專制君主、帝制朝代（如新朝王莽、唐玄宗濫權）、當代獨裁國家（如北韓）</td><td>現代民主憲政國家（如我國、美國）</td></tr></tbody></table></div><h3>2. 「權利」（Right） vs 「權力」（Power） 比較表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>權利（Right）</th><th>權力（Power）</th></tr></thead><tbody><tr><td><b>定義</b></td><td>人民在法律保障下，享有免受任意侵害且能<b>追求合法利益的權益</b></td><td>個人、團體或政府機關擁有優勢資源，以<b>強制力量影響他人行為</b>並執行事務的能力</td></tr><tr><td><b>主體歸屬</b></td><td>歸屬於<b>人民</b>（公民個人或私法人團體）</td><td>主要由<b>政府機關及其公務員</b>代表國家行使（即公權力）</td></tr><tr><td><b>行使目的</b></td><td>實現個人生活利益、追求幸福、維護自身尊嚴與自由</td><td>維護公共安全、維持社會秩序、推動公共建設與福利</td></tr><tr><td><b>法治約束</b></td><td>人民享有之各項基本權利受憲法明文保障，不得無故剝奪</td><td>行使時必須受法律嚴格限制，必須符合法令授權與正當法律程序</td></tr><tr><td><b>典型生活情境</b></td><td>1. 警察無搜索票欲進屋搜索時，人民依法<b>拒絕開門入內</b>&lt;br&gt;2. 人民依法進行請願、集會遊行或參政投票&lt;br&gt;3. 受非法侵害時向法院提起訴訟請求救濟</td><td>1. 警察依《警職法》執行<b>路邊酒駕臨檢</b>與交通管制&lt;br&gt;2. 法院核發合法搜索票，檢警依法進行住宅搜查&lt;br&gt;3. 政府機關對違章建築執行強制拆除或開罰</td></tr></tbody></table></div><h3>3. 孟德斯鳩「三權分立」 vs 孫中山「五權分立」 比較表</h3><div class=\"tbl\"><table><thead><tr><th>比較面向</th><th>三權分立（西方體制）</th><th>五權分立（我國體制）</th></tr></thead><tbody><tr><td><b>倡導學者</b></td><td>法國啟蒙思想家 <b>孟德斯鳩</b></td><td>中華民國國父 <b>孫中山</b> 先生</td></tr><tr><td><b>制度共同目的</b></td><td><b>防止權力過度集中與濫用，保障人民自由與權利</b></td><td><b>防止政府濫權，建構受憲法約束之有限政府</b></td></tr><tr><td><b>劃分權限數量</b></td><td><b>三權</b>：行政權、立法權、司法權</td><td><b>五權</b>：行政權、立法權、司法權、考試權、監察權</td></tr><tr><td><b>考試權歸屬</b></td><td>涵蓋於<b>行政權</b>之中（由各行政機關自行掌理人員考用）</td><td>自行政權中<b>獨立為「考試院」</b>，負責國家考試選拔人才及公務員銓敘保障</td></tr><tr><td><b>考試權獨立動機</b></td><td>西方認為內閣或首長可直接選用政務人員以推動政策</td><td>避免行政部門兼具用人與考選資格之權，產生<b>濫用私人、任用親信</b>的缺陷（如唐玄宗重用口蜜腹劍之李林甫）</td></tr><tr><td><b>監察權歸屬</b></td><td>涵蓋於<b>立法權</b>之中（由國會議員兼負彈劾、調查與糾正行政院之責）</td><td>自立法權中<b>獨立為「監察院」</b>，專責彈劾、糾舉失職官員並提出糾正案</td></tr><tr><td><b>監察權獨立動機</b></td><td>國會藉由質詢、調查與不信任案發揮監督功能</td><td>避免議會民意代表兼握立法與監察大權，形成<b>國會專制、議會獨裁</b>的弊端</td></tr><tr><td><b>司法權定位</b></td><td>獨立於行政與立法之外，以客觀法律裁決兩者之政黨爭執與利益衝突</td><td>獨立於其他四權之外，各級法院獨立審判，司法院大法官組成憲法法庭守護憲法秩序</td></tr><tr><td><b>代表國家</b></td><td>美國、法國等西方民主國家</td><td>中華民國（臺灣）</td></tr></tbody></table></div>"}, {"id": "timeline", "title": "思想演進", "html": "<h3>思想演進時間軸</h3><div class=\"tbl\"><table><thead><tr><th>年代／時期</th><th>關鍵人物／重要文獻</th><th>重點與思想核心貢獻</th></tr></thead><tbody><tr><td><b>西漢／新朝（古代帝制）</b></td><td>漢朝帝王、王莽改制</td><td><b>人治社會典型</b>：統治者憑好惡改動法規制度，朝令夕改，公權力缺乏客觀法規拘束，導致百姓權利遭受重大剝奪。</td></tr><tr><td><b>17 世紀末（啟蒙時代）</b></td><td>英國哲學家 <b>洛克（John Locke）</b></td><td><b>近代分權思想萌芽</b>：主張人民委託權力給政府，旨在保障生命、自由與財產；政府職權必須交由不同機關行使，以避免權力過度集中。</td></tr><tr><td><b>18 世紀中（1748年）</b></td><td>法國思想家 <b>孟德斯鳩（Montesquieu）</b></td><td><b>奠定「三權分立」理論</b>：於著作中論證「立法與行政若集中同一人手，自由便不復存在」；確立行政、立法、司法三權互相分立牽制的架構。</td></tr><tr><td><b>19 世紀末（1887年）</b></td><td>英國歷史學者 <b>艾克頓爵士（Lord Acton）</b></td><td><b>提出權力本質警語</b>：「權力使人腐化，絕對的權力，絕對的腐化」，從人性與權力關係說明權力分立與制衡機制不可或缺的理論基礎。</td></tr><tr><td><b>20 世紀初</b></td><td><b>孫中山</b> 先生</td><td><b>創立「五權分立」學說</b>：吸納三權分立精髓並改進其弊端，將考試權從行政權獨立、監察權從立法權獨立，建立我國五院中央政府憲政體制。</td></tr><tr><td><b>現代民主憲政實踐</b></td><td>現代法治國家憲法法規</td><td><b>建構「有限政府」</b>：各國以憲法界定政府權能上限，透過司法違憲審查、國會監督與權力分立，落實保障人權的憲政根本精神。</td></tr></tbody></table></div><h3>中央政府預決算分權制衡流程</h3><figure class=\"cimg\"><img src=\"img/c4-map-budget.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中央政府預算、決算流程簡圖</figcaption></figure><pre class=\"flow\">【行政院】編列中央政府各院總預算案\n     ↓ 送交審查\n【立法院】依法審查並議決預算案（監督行政機關施政方向）\n     ↓ 預算案三讀通過，行政機關據以執行\n【行政院】執行預算、施政推動，並於年度終了做成決算\n     ↓ 送交審核\n【監察院審計部】審核決算，並編製年度決算審核報告\n     ↓ 送交審議\n【立法院】審議審計部之審核報告，完成分權監督流程</pre>"}, {"id": "charts", "title": "圖表判讀", "html": "<h3>1. 人治與法治對照示意圖</h3><p class=\"li\"><b>圖表名稱</b>：人治社會與法治社會之治理模式對比圖。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>法律的源頭與地位</b>：人治圖示中，統治者高高在上，身後標示「統治者的意思就是法律」、「統治者可隨意變更法律」，跪拜的百姓承受壓迫；法治圖示中，法律被捧為最高準則，圖示中法律如同盾牌「限制統治者的權力」，官員依循法律條文向民眾執法（「執法有明確法律依據」），底層標註「人民選出代表制定法律」。</p><p class=\"li sub\">2. <b>箭頭方向與約束範圍</b>：人治的規範僅由上往下強制加諸人民；法治的規範則是「法在中央/最高位」，同時雙向約束統治者（政府）與人民。</p><p class=\"li\"><b>常見判讀方式與考點</b>：</p><p class=\"li sub\">• 題目常以國王說「我就是法律」、官員「依長官心情臨時修改規則」入題，考生需秒判為<b>人治模式</b>。</p><p class=\"li sub\">• 只要出現「警察臨檢依據法律條例」、「人民要求出示搜索票否則拒絕搜索」，即為法治社會之<b>依法行政</b>與<b>權利保障</b>特徵。</p><h3>2. 「權利」與「權力」情境辨析圖</h3><p class=\"li\"><b>圖表名稱</b>：日常生活情境之權利（Right）與權力（Power）判讀圖。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>情境一（公權力行使）</b>：圖中員警向駕駛出示證件並示意攔停進行酒測臨檢（駕駛座旁寫有「請依法配合酒駕臨檢」）。此處員警代表政府執行公務，運用優勢法規強制力維護交安，屬於<b>權力（Power）</b>的合法施展。</p><p class=\"li sub\">2. <b>情境二（基本權利行使）</b>：圖中便衣警察欲入內搜查民宅，民眾站在門口嚴正表示「沒有搜索票，你不能進來！」。此處民眾行使憲法保障之人身自由與居住自由，依法阻卻違法搜查，屬於<b>權利（Right）</b>的防衛主張。</p><p class=\"li\"><b>常見判讀方式與考點</b>：</p><p class=\"li sub\">• 先看行為主體：<b>官員／政府依行政法規處罰或命令人民</b> → 多屬<b>權力</b>；<b>人民自主決定、參政、或請求法律救濟／拒絕不法侵害</b> → 多屬<b>權利</b>。</p><p class=\"li sub\">• 陷阱題：「國家考試的考生免用入場證」→ 是考選機關行使「權力」調整規則，但考生享有的是「應考試」之基本「權利」。</p><h3>3. 三權分立與五權分立架構圖</h3><figure class=\"cimg\"><img src=\"img/c3-map-powers.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>三權分立與五權分立示意圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：孟德斯鳩三權分立與孫中山五權分立機關架構圖。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>三權分立圖</b>：行政權、立法權、司法權三立並列，彼此之間有雙向箭頭代表相互制衡。</p><p class=\"li sub\">2. <b>五權分立圖</b>：孫中山先生圖旁羅列「行政權、立法權、司法權、考試權、監察權」五個平行的獨立柱體。下方特別標示：</p><p class=\"li sub\">• 考試權獨立宗旨：<b>為國公正舉才，避免濫用私人</b>。</p><p class=\"li sub\">• 監察權獨立宗旨：<b>確實監督政府機關，杜絕國會專制</b>。</p><p class=\"li\"><b>常見判讀方式與考點</b>：</p><p class=\"li sub\">• 會考選擇題常以填空框「甲、乙」遮住考試權與監察權，提示「從行政權獨立出」必為<b>考試權</b>；「從立法權獨立出」必為<b>監察權</b>。</p><p class=\"li sub\">• 若題幹出現「某國總統兼任國會議長，且可直接干預最高法院審判」，圖表判讀為<b>嚴重破壞權力分立原則</b>，易導致無限政府與專政。</p>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>特別提醒（會考熱門陷阱）</h3><p>1. <b>「法治」不等於「有很多法律」</b>：人治國家的專制獨裁者同樣會制定繁多的嚴刑峻法（如古代法家嚴刑苛法），但只要統治者自身不受法律拘束、將法律當作整肅人民的工具，本質仍是「<b>人治</b>」而非法治。</p><p>2. <b>法治國家的最高依歸</b>：法治國家中「法律大於國王／總統」，公權力的行使必須有法律明確授權，且任何法律與命令均不得牴觸具有最高性的《憲法》。</p><p>3. <b>分權的目的不是追求效率</b>：權力分立制度的設計本意在於<b>防範專制濫權、保障人民權利</b>，並非為了提升施政效率（分權相互牽制往往需要更多協商時間）。</p><p>4. <b>考試權獨立的防弊重點</b>：防止「行政首長私相授受、任用親信用人唯親」；<b>監察權獨立的防弊重點</b>：防止「立法機關兼握彈劾調查權而形成國會專制濫權」。</p><h3>考前速記口訣</h3><div class=\"poem\">💡 <b>口訣一：治理模式辨析</b></div><div class=\"poem\"><b>「人治王大於法、法治法大於官；依法行政受約束，人民權利有保障。」</b></div><div class=\"poem\">*(人治看君王好惡，法治看法律授權；政府依法行政受限，人民權利方能落實)。*</div><div class=\"poem\">💡 <b>口訣二：分權理論源流</b></div><div class=\"poem\"><b>「艾克頓防腐化、孟德斯鳩立三權；中山先生創五權，考政獨立監國會。」</b></div><div class=\"poem\">*(艾克頓名言權力使人腐化；孟德斯鳩提行政、立法、司法三權；孫中山創五權，考試權自行政權獨立、監察權自立法權獨立)。*</div><div class=\"poem\">💡 <b>口訣三：權力 vs 權利</b></div><div class=\"poem\"><b>「公家強制稱『權力』，人民享受是『權利』；權力行使依法令，侵犯權利民可抗。」</b></div><div class=\"poem\">*(警察開單為權力行使，無票拒搜為權利維護)。*</div>"}]});
